const initial:State={profile:null,assessment:{},assessmentComplete:false,assessmentSessionId:null,assessmentQuestionIds:riasecQuestions.map(question=>question.id),assessmentIndex:0,assessmentHistory:[],career:'',done:[],entries:[],saved:[],roadmapNodes:[],dismissedSuggestions:[]};
const demoCareerSeeds:Omit<Career,'riasecDimensions'|'skillRequirements'|'details'>[]=[
 {id:'data',name:'Data Scientist',group:'Technology',desc:'Use data, statistics, and code to understand patterns and help people make informed decisions.',interests:['analysis','solving problems','research'],skills:['Python','Data analysis','Statistics','Communication'],path:'Explore mathematics, statistics, and programming; build a foundation through small data projects and study options in data science or related fields.',consider:'Day-to-day work can involve cleaning data, explaining uncertainty, and collaborating across teams. Explore the subject requirements and pathways where you live.'},
 {id:'software',name:'Software Developer',group:'Technology',desc:'Design, build, test, and improve software used by people and organizations.',interests:['building things','solving problems','technology'],skills:['Programming','Problem solving','Version control','Communication'],path:'Start with programming fundamentals, then build and share small projects. Computer science, software engineering, and related courses are possible pathways.',consider:'The work often includes debugging, reading existing code, and learning new tools. Entry requirements and role expectations vary.'},
 {id:'designer',name:'Product Designer',group:'Design',desc:'Make digital products easier to understand and use through research, interaction design, and visual craft.',interests:['design','people','building things'],skills:['User research','Prototyping','Visual design','Communication'],path:'Learn design fundamentals, observe how people use products, and build a portfolio that explains your decisions. Explore design, HCI, and related study pathways.',consider:'Product design is collaborative and iterative. Portfolios show process as well as polished screens; roles differ across organizations.'},
 {id:'research',name:'Research Analyst',group:'Research',desc:'Investigate questions, evaluate evidence, and communicate findings clearly.',interests:['research','analysis','writing'],skills:['Research','Critical thinking','Data analysis','Writing'],path:'Strengthen research methods and communication. Explore subject-focused degrees and opportunities to practice structured inquiry.',consider:'The subject area shapes the work. Check the methods, qualifications, and context expected for roles that interest you.'}
];
const demoCareerDimensions:Record<string,string[]>={data:['I','C'],software:['R','I','E'],designer:['A','S','E'],research:['I','S','C']};
const demoCareers:Career[]=demoCareerSeeds.map(career=>({...career,riasecDimensions:demoCareerDimensions[career.id]||[],skillRequirements:career.skills.map(name=>({id:name.toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/(^-|-$)/g,''),name,notes:`Explore ${name.toLowerCase()} through a beginner activity.`,relevance:'relevant'})),details:{pathway:career.path,consider:career.consider}}));
type CareerCatalogValue={careers:Career[];skills:SkillDefinition[];loading:boolean;error:string};
const CareerCatalogContext=createContext<CareerCatalogValue>({careers:demoCareers,skills:[],loading:false,error:''});
function CareerCatalogProvider({children}:{children:ReactNode}){const [careers,setCareers]=useState<Career[]>(demoCareers);const [skills,setSkills]=useState<SkillDefinition[]>([]);const [loading,setLoading]=useState(!!supabase);const [error,setError]=useState('');useEffect(()=>{if(!supabase)return;let active=true;Promise.all([loadCareerCatalog(),loadSkillCatalog()]).then(([rows,skillRows])=>{if(!rows.length)throw new Error('No published career rows were returned.');if(active){setCareers(rows);setSkills(skillRows);setError('');}}).catch(e=>{if(active){setCareers(demoCareers);setError(e instanceof Error?e.message:'Career catalog could not be loaded.');}}).finally(()=>{if(active)setLoading(false);});return()=>{active=false;};},[]);return <CareerCatalogContext.Provider value={{careers,skills,loading,error}}>{children}</CareerCatalogContext.Provider>}
function useCareerCatalog(){return useContext(CareerCatalogContext)}
function toggleSavedCareer(state:State,setState:(state:State)=>void,userId:string|undefined,careerId:string,onError:(message:string)=>void){const saved=state.saved.includes(careerId);if(!userId||!supabase){setState({...state,saved:saved?state.saved.filter(id=>id!==careerId):[...state.saved,careerId]});return;}void setSavedCareer(userId,careerId,!saved).then(()=>setState({...state,saved:saved?state.saved.filter(id=>id!==careerId):[...state.saved,careerId]})).catch(error=>onError(error instanceof Error?error.message:'Could not update saved careers.'));}
function CareerCatalogNotice(){const {loading,error}=useCareerCatalog();if(!loading&&!error)return null;return <div className={error?'notice':'panel'} role={error?'alert':'status'}>{loading?'Loading published careers and skills from Supabase…':`Career catalog unavailable: ${error} Showing the local demo catalog.`}</div>}
type SyncStatus='local'|'loading'|'ready'|'saving'|'saved'|'error';
const SyncStatusContext=createContext<SyncStatus>('local');
type AuthFeedback={notice:string;setNotice:(value:string)=>void};
const AuthFeedbackContext=createContext<AuthFeedback>({notice:'',setNotice:()=>{}});
const read=():State=>{try{const saved=JSON.parse(localStorage.getItem('aayam-demo')||'{}');return {...initial,...saved,assessment:saved.assessment&&!Array.isArray(saved.assessment)?saved.assessment:{},assessmentQuestionIds:Array.isArray(saved.assessmentQuestionIds)?saved.assessmentQuestionIds:initial.assessmentQuestionIds,assessmentHistory:Array.isArray(saved.assessmentHistory)?saved.assessmentHistory:[],roadmapNodes:Array.isArray(saved.roadmapNodes)?saved.roadmapNodes:[]};}catch{return initial;}};
function useStore(){const [state,setState]=useState<State>(read);useEffect(()=>{if(!supabase)localStorage.setItem('aayam-demo',JSON.stringify(state));},[state]);return [state,setState] as const;}
function Logo(){return <Link className="brand" to="/"><span className="brandmark">A</span><span><b>AAYAM</b><small>EXPLORE · LEARN · BUILD</small></span></Link>}
function Button({children,to,onClick,kind='primary',type='button'}:{children:ReactNode;to?:string;onClick?:()=>void;kind?:string;type?:'button'|'submit'}){return to?<Link className={`button ${kind}`} to={to}>{children}</Link>:<button className={`button ${kind}`} type={type} onClick={onClick}>{children}</button>}
const featureList=[['Adaptive Student Profile','A profile that starts with your current stage and goals.',UserRound,'/onboarding'],['Career Assessment','Reflect on your interests and preferred ways of working.',Target,'/assessment'],['Career Discovery','Explore options with clear reasons to investigate each path.',Compass,'/careers'],['Career Reality Check','See responsibilities, pathways, and questions to research.',BriefcaseBusiness,'/careers/data'],['Skill Gap Analyzer','Separate skills you have evidence for from those to develop.',BarChart3,'/skills'],['Adaptive Career Roadmap','Turn a direction into practical learning milestones.',BookOpen,'/roadmap'],['Progress Dashboard','See what you have explored and choose a useful next step.',Sparkles,'/app'],['Portfolio & Evidence Tracker','Keep projects and learning evidence in one place.',FolderOpen,'/portfolio']] as const;
function Landing(){const {careers,skills,loading,error}=useCareerCatalog();const career=careers[0];const previewSkills=career?.skillRequirements.map(requirement=>({id:requirement.id,name:requirement.name,description:skills.find(skill=>skill.id===requirement.id)?.description||requirement.notes||`Explore ${requirement.name.toLowerCase()} through a beginner learning activity.`}))||[];return <div className="landing"><header className="site-nav wrap"><Logo/><nav className="desktop-nav"><a href="#home">Home</a><a href="#how">How it works</a><Link to="/careers">Explore Careers</Link><a href="#students">For Students</a><a href="#about">About</a></nav><div className="nav-actions"><Link className="signin" to="/signin">Sign in</Link><Button to="/onboarding">Get started <ArrowRight size={16}/></Button></div></header>
<main><section className="hero wrap" id="home"><div className="hero-copy"><p className="eyebrow">YOUR FUTURE, WITH DIRECTION</p><h1>Your future isn’t a guess.<br/><em>Build it with Aayam.</em></h1><p className="lead">Explore careers that match your interests, understand what each path requires, identify the skills you need, and build a personalized roadmap to achieve your goals.</p><div className="hero-actions"><Button to="/onboarding">Discover my path <ArrowRight size={17}/></Button><a className="text-link" href="#how">How it works <ArrowDown size={16}/></a></div><div className="value-row">{[['Explore suitable careers',Compass],['Identify skill gaps',BarChart3],['Build a personalized roadmap',BookOpen]].map(([label,Icon])=><div className="value" key={label as string}><span className="icon-bubble"><Icon size={20}/></span><b>{label as string}</b></div>)}</div></div>
<div className="hero-art"><div className="contour contour-one"/><div className="contour contour-two"/>{career&&<SculptureCanvas careerName={career.name} careerDescription={career.desc} skills={previewSkills} sourceLabel={dataMode==='local-demo'?'Sample catalog preview':error?'Demo catalog preview':loading?'Loading published catalog':'Published catalog preview'}/>}</div></section>
<section className="how section wrap" id="how"><div className="section-heading"><p className="eyebrow">HOW AAYAM WORKS</p><h2>A simple path to a <span>brighter future</span></h2><p>From understanding yourself to building real skills — Aayam guides you at every step.</p></div><div className="steps">{[['Build your profile','Tell us about your academic background, interests and goals.',UserRound],['Explore your strengths','Reflect on the activities and problems that energize you.',FileText],['Discover and compare careers','Explore possibilities with clear, practical context.',BarChart3],['Build skills and track evidence','Follow a learning plan and collect examples of your work.',FolderOpen]].map(([title,desc,Icon],i)=><article className="step-card" key={title as string}><span className="step-num">0{i+1}</span><Icon size={25}/><h3>{title as string}</h3><p>{desc as string}</p></article>)}</div></section>
<section className="features section" id="students"><div className="wrap feature-layout"><div className="feature-intro"><p className="eyebrow">THE COMPLETE CAREER GUIDANCE EXPERIENCE</p><h2>Everything you need to move forward</h2><p>Aayam brings together career discovery, skill development and evidence tracking into one connected experience.</p><Button to="/careers" kind="secondary">Explore careers <ArrowRight size={16}/></Button></div><div className="feature-grid">{featureList.map(([title,desc,Icon,path])=><Link to={path} className="feature-card" key={title}><span><Icon size={21}/></span><div><h3>{title}</h3><p>{desc}</p></div><ArrowUpRight className="feature-arrow" size={16}/></Link>)}</div></div></section>
<section className="discover-band wrap"><div><p className="eyebrow">A GOOD NEXT STEP STARTS WITH A QUESTION</p><h2>Turn curiosity into a direction.</h2><p>Try a guided demo, explore different paths, and decide what you want to learn next.</p></div><Button to="/onboarding">Start exploring <ArrowRight size={16}/></Button></section></main><footer className="footer wrap" id="about"><Logo/><span>Career exploration, made more thoughtful.</span><span>Demo experience · No account required</span></footer></div>}
function Shell({children,title,subtitle}:{children:ReactNode;title:string;subtitle:string}){const [open,setOpen]=useState(false);const syncStatus=useContext(SyncStatusContext);const [signingOut,setSigningOut]=useState(false);const [signOutError,setSignOutError]=useState('');const authFeedback=useContext(AuthFeedbackContext);const navigate=useNavigate();const signOut=async()=>{if(!supabase)return;setSigningOut(true);setSignOutError('');authFeedback.setNotice('');try{const {error}=await supabase.auth.signOut();if(error)throw error;authFeedback.setNotice('You have signed out.');navigate('/signin',{replace:true});}catch(e){setSignOutError(e instanceof Error?e.message:'Sign out failed. Please try again.');}finally{setSigningOut(false);}};const links=[['Overview','/app',Sparkles],['My Profile','/profile',UserRound],['Career Intelligence','/career-intelligence',Sparkles],['Career Explorer','/career-explorer',Compass],['3D Path Explorer','/career-universe',Compass],['Assessment Centre','/assessment',Target],['Skill Gap Analyzer','/skills',BarChart3],['My Roadmaps','/my-roadmaps',BookOpen],['Roadmap Generator','/roadmap-generator',Plus],['My Portfolio','/portfolio',FolderOpen]] as const;return <div className="app-shell"><aside className={`sidebar ${open?'show':''}`}><Logo/><button className="mobile-close" aria-label="Close navigation" onClick={()=>setOpen(false)}><X/></button><div className="side-label">YOUR WORKSPACE</div><nav>{links.map(([label,path,Icon])=><NavLink onClick={()=>setOpen(false)} className={({isActive})=>`side-link ${isActive?'active':''}`} to={path} key={path}><Icon size={18}/>{label}</NavLink>)}</nav><div className="side-bottom"><div className="side-note"><Lightbulb size={18}/><p>Explore at your own pace. Your plan can change as you learn.</p></div>{supabase?<><button onClick={()=>void signOut()} disabled={signingOut} className="reset-button">{signingOut?'Signing out…':'Sign out'}</button>{signOutError&&<p className="form-error" role="alert">{signOutError}</p>}</>:<button onClick={()=>{localStorage.removeItem('aayam-demo');location.href='/';}} className="reset-button">Reset demo data</button>}<Link to="/" className="back-home">← Back to Aayam</Link></div></aside>{open&&<button className="scrim" aria-label="Close navigation" onClick={()=>setOpen(false)}/>}
<main className="app-main"><header className="app-topbar"><button className="menu-toggle" aria-label="Open navigation" onClick={()=>setOpen(true)}><Menu/></button><div className="crumb">Aayam <ChevronRight size={14}/> Workspace</div><div className="top-actions"><span className="demo-chip" role="status" aria-live="polite">{dataMode==='local-demo'?'LOCAL DEMO':syncStatus==='loading'?'LOADING CLOUD DATA':syncStatus==='saving'?'SAVING TO SUPABASE':syncStatus==='saved'?'SAVED TO SUPABASE':syncStatus==='error'?'SYNC ERROR':'SUPABASE READY'}</span><span className="avatar">{title.startsWith('Good')?'R':'A'}</span></div></header><div className="page-content"><div className="page-title"><div><p className="eyebrow">YOUR CAREER JOURNEY</p><h1>{title}</h1><p>{subtitle}</p></div></div><CareerCatalogNotice/>{children}</div></main></div>}
function Dashboard({state,userId}:{state:State;userId?:string}){
 const {careers}=useCareerCatalog();const career=careers.find(c=>c.id===state.career)||careers[0];
 const [roadmaps,setRoadmaps]=useState<RoadmapSummary[]>(()=>{try{return JSON.parse(localStorage.getItem(`aayam-roadmaps:${userId||'demo'}`)||'[]') as RoadmapSummary[]}catch{return[]}});
 const [skillEvidence,setSkillEvidence]=useState<SkillEvidence[]>([]);const [dataError,setDataError]=useState('');
 useEffect(()=>{let active=true;if(userId){Promise.all([listRoadmaps(userId),loadSkillEvidence(userId)]).then(([roadmapRows,evidenceRows])=>{if(active){setRoadmaps(roadmapRows);setSkillEvidence(evidenceRows);setDataError('');}}).catch(error=>{if(active)setDataError(error instanceof Error?error.message:'Dashboard data could not be loaded.');});}else{try{setRoadmaps(JSON.parse(localStorage.getItem('aayam-roadmaps:demo')||'[]'));const records=JSON.parse(localStorage.getItem('aayam-demo-skill-evidence')||'[]');setSkillEvidence(records);}catch{setRoadmaps([]);setSkillEvidence([]);}}return()=>{active=false;};},[userId]);
 const activeRoadmap=roadmaps.find(item=>item.status==='active');const roadmapTasks=activeRoadmap?.tasks||[];const currentRoadmapNodes=state.roadmapNodes;const doneCount=activeRoadmap?roadmapTasks.filter(task=>task.status==='completed').length:currentRoadmapNodes.filter(node=>state.done.includes(node.id)).length;const total=activeRoadmap?roadmapTasks.length:currentRoadmapNodes.length;const nextTask=activeRoadmap?.tasks.find(task=>task.status!=='completed');const nextNode=currentRoadmapNodes.find(node=>!state.done.includes(node.id));const nextTitle=nextTask?.title||nextNode?.title;const nextDescription=nextTask?.description||nextNode?.desc;
 const supportedSkillIds=new Set(skillEvidence.filter(item=>item.evidence_type!=='self_reported').map(item=>item.skill_id));const portfolioSkillIds=new Set(state.entries.map(entry=>entry.skillId).filter((id):id is string=>!!id));const evidencedSkillIds=userId?supportedSkillIds:portfolioSkillIds;const evidencedCount=career.skillRequirements.filter(skill=>evidencedSkillIds.has(skill.id)).length;const assessmentResult=scoreAssessment(state.assessment,state.assessmentQuestionIds);
 const savedCareers=careers.filter(item=>state.saved.includes(item.id));
 return <Shell title={`Good day${state.profile?.name?`, ${state.profile.name}`:''}.`} subtitle="A thoughtful next step is better than having it all figured out.">{dataError&&<p className="form-error" role="alert">Some dashboard data could not be loaded: {dataError}</p>}<div className="dashboard-grid"><article className="panel wide direction-panel"><div><div className="panel-label">{state.career?'CAREER DIRECTION':'GET STARTED'} <span className="tag sage-tag">{state.career?'Exploring':'No direction selected'}</span></div><h2>{state.career?career.name:'Choose a career to explore'}</h2><p>{state.career?career.desc:'Review transparent career matches or browse the career catalog when you are ready.'}</p><div className="panel-actions"><Button to={state.career?`/careers/${career.id}`:'/career-intelligence'}>{state.career?'Explore this career':'Find options to explore'} <ArrowRight size={15}/></Button><Link to="/career-explorer" className="text-link">Browse the catalog</Link></div></div><span className="big-icon"><Compass size={40}/></span></article>
 <article className="panel next-panel"><div className="panel-label">YOUR NEXT STEP</div><h3>{nextTitle||'Start with a goal'}</h3><p>{nextDescription||'Create a roadmap for a career, skill, or project you want to explore.'}</p><div className="mini-progress"><span style={{width:`${total?doneCount/total*100:0}%`}}/></div><div className="progress-copy">{total?`${doneCount} of ${total} tasks complete`:'No active roadmap yet'}</div><Button to={total?'/my-roadmaps':'/roadmap-generator'} kind="secondary">{total?'Continue roadmap':'Create a roadmap'} <ArrowRight size={14}/></Button></article>
 <article className="panel"><div className="panel-label">RIASEC INTERESTS</div>{assessmentResult.top.length?<><h3>{assessmentResult.top.map(d=>dimensions[d].name).join(' · ')}</h3><p>Reflection score from {Object.keys(state.assessment).length} answered activities.</p></>:<><h3>No assessment results yet</h3><p>Answer the RIASEC reflection when you are ready.</p></>}<Link to="/assessment" className="inline-link">{assessmentResult.top.length?'Review results':'Start reflecting'} <ArrowRight size={14}/></Link></article>
 <article className="panel"><div className="panel-label">SAVED CAREERS</div>{savedCareers.length?<><h3>{savedCareers.length} saved</h3><p>{savedCareers.slice(0,2).map(item=>item.name).join(' · ')}</p></>:<><h3>No saved careers yet</h3><p>Save a career from recommendations or the explorer.</p></>}<Link to="/career-explorer" className="inline-link">{savedCareers.length?'Review saved careers':'Explore careers'} <ArrowRight size={14}/></Link></article>
 <article className="panel"><div className="panel-label">SKILL EVIDENCE · {state.career?career.name:'SELECT A GOAL'}</div><h3>{state.career?`${evidencedCount} linked to catalog requirements`:'No career goal selected'}</h3><p>{state.career?'Self-reported skill notes are not counted as demonstrated evidence.':'Choose a career to review its catalog skill requirements.'}</p><Link to="/skills" className="inline-link">Review skills <ArrowRight size={14}/></Link></article>
 <article className="panel"><div className="panel-label">PORTFOLIO</div><h3>{state.entries.length} {state.entries.length===1?'entry':'entries'}</h3><p>{state.entries[0]?.title||'Add a project or learning note when you are ready.'}</p><Link to="/portfolio" className="inline-link">Open portfolio <ArrowRight size={14}/></Link></article></div><div className="section-row"><h2>Choose where to go next</h2></div><div className="shortcut-grid"><Link to="/career-intelligence"><Sparkles/><b>Review career matches</b><span>See why each career appears</span><ArrowRight/></Link><Link to="/my-roadmaps"><BookOpen/><b>Manage your roadmaps</b><span>Continue or create another goal</span><ArrowRight/></Link><Link to="/portfolio"><FolderOpen/><b>Collect your evidence</b><span>Capture work and learning</span><ArrowRight/></Link></div></Shell>
}
function Onboarding({state,setState}:{state:State;setState:(s:State)=>void}){const [step,setStep]=useState(0);const profile=state.profile||{name:'',stage:'School',study:'',interests:[],goal:'',time:'3–5 hours'};const patch=(v:Partial<Profile>)=>setState({...state,profile:{...profile,...v}});const stages=['School','College','Graduate / early career','Working professional'];const interestOptions=['Design','Analysis','Technology','Research','People','Building things','Writing','Solving problems'];return <Shell title="Build your profile" subtitle="A few details help shape a more relevant exploration. You can change these later."><div className="wizard panel"><div className="wizard-progress"><div className="wizard-progress-head"><span>STEP {step+1} OF 4</span><span>{Math.round((step+1)/4*100)}% complete</span></div><div className="progress-track"><span style={{width:`${(step+1)*25}%`}}/></div></div>{step===0&&<div className="wizard-step"><h2>First, what should we call you?</h2><p>We’ll use this to personalize your workspace.</p><label>Display name<input value={profile.name} onChange={e=>patch({name:e.target.value})} placeholder="Your name"/></label><label>What best describes your current stage?<select value={profile.stage} onChange={e=>patch({stage:e.target.value})}>{stages.map(s=><option key={s}>{s}</option>)}</select></label></div>}{step===1&&<div className="wizard-step"><h2>Tell us about what you’re studying</h2><p>We’ll adapt the next question to your current stage.</p><label>{profile.stage==='School'?'Current class':profile.stage==='College'?'Degree and year':profile.stage==='Working professional'?'Current professional area and experience':'Qualification or area of experience'}<input value={profile.study} onChange={e=>patch({study:e.target.value})} placeholder={profile.stage==='School'?'e.g. Class 11 · Science':profile.stage==='College'?'e.g. B.Des · Year 2':profile.stage==='Working professional'?'e.g. Education · 3 years':'e.g. Commerce graduate'}/></label><label>Time you could spend learning each week<select value={profile.time} onChange={e=>patch({time:e.target.value})}>{['1–2 hours','3–5 hours','6–10 hours','It varies'].map(x=><option key={x}>{x}</option>)}</select></label></div>}{step===2&&<div className="wizard-step"><h2>What are you curious about?</h2><p>Choose any that sound interesting. This is a starting point, not a test.</p><div className="choice-grid">{interestOptions.map(item=><button key={item} className={`choice ${profile.interests.includes(item)?'selected':''}`} onClick={()=>patch({interests:profile.interests.includes(item)?profile.interests.filter(x=>x!==item):[...profile.interests,item]})}>{profile.interests.includes(item)&&<Check size={16}/>} {item}</button>)}</div><label>What would you like to explore? <input value={profile.goal} onChange={e=>patch({goal:e.target.value})} placeholder="A subject, skill, or career question"/></label></div>}{step===3&&<div className="wizard-step"><h2>Your exploration profile</h2><p>Review what you shared before continuing.</p><div className="review-list"><p><b>Name</b><span>{profile.name||'Not provided'}</span></p><p><b>Stage</b><span>{profile.stage} · {profile.study||'Study details not provided'}</span></p><p><b>Curious about</b><span>{profile.interests.join(', ')||'Not selected yet'}</span></p><p><b>Weekly learning time</b><span>{profile.time}</span></p></div><div className="notice"><Lightbulb size={17}/> Your profile stays in this browser as demo data. You can reset it from the workspace.</div></div>}<div className="wizard-footer">{step>0?<button className="button secondary" onClick={()=>setStep(step-1)}><ChevronLeft size={16}/> Back</button>:<span/>}{step<3?<button className="button primary" onClick={()=>setStep(step+1)}>Continue <ChevronRight size={16}/></button>:<Button to="/assessment" onClick={()=>{setState({...state,profile});}}>Save profile and continue <ArrowRight size={16}/></Button>}</div></div></Shell>}
function Assessment({state,setState,userId,ready,saveState,saveError,onSaveAssessment}:{state:State;setState:(s:State)=>void;userId?:string;ready:boolean;saveState:'idle'|'saving'|'saved'|'error';saveError:string;onSaveAssessment:(responses:Responses,sessionId:string|null,questionIds:string[],index:number)=>Promise<string>}){
 const {careers}=useCareerCatalog();
 const [compareIds,setCompareIds]=useState<string[]>([]); const [attemptError,setAttemptError]=useState('');
 const questionIds=state.assessmentQuestionIds.length?state.assessmentQuestionIds:riasecQuestions.map(question=>question.id);
 const questionSet=questionIds.map(id=>riasecQuestions.find(question=>question.id===id)).filter((question):question is typeof riasecQuestions[number]=>!!question);
 const indexKey=`aayam-assessment-index:${userId||'demo'}`;
 const initialIndex=()=>{const storedIndex=state.assessmentIndex;if(Number.isInteger(storedIndex)&&storedIndex>=0&&storedIndex<questionSet.length)return storedIndex;try{const stored=localStorage.getItem(indexKey);if(stored!==null){const parsed=Number(stored);if(Number.isInteger(parsed)&&parsed>=0&&parsed<questionSet.length)return parsed;}}catch{}const firstUnanswered=questionSet.findIndex(question=>state.assessment[question.id]===undefined);return firstUnanswered<0?questionSet.length-1:firstUnanswered;};
 const [index,setIndexState]=useState(initialIndex); const result=scoreAssessment(state.assessment,questionIds); const answered=questionIds.filter(id=>state.assessment[id]!==undefined).length;
 const setIndex=(next:number)=>{const value=Math.max(0,Math.min(next,questionSet.length-1));setIndexState(value);setState({...state,assessmentIndex:value});try{localStorage.setItem(indexKey,String(value));}catch{}if(userId&&state.assessmentSessionId)void saveAssessmentPosition(userId,state.assessmentSessionId,value).catch(problem=>setAttemptError(problem instanceof Error?problem.message:'Could not save assessment position.'));};
 const q=questionSet[index]||riasecQuestions[0];
 const suggested=suggestCareers(result.top,careers).filter(s=>!state.dismissedSuggestions.includes(s.careerId)).map(s=>({...s,career:careers.find(c=>c.id===s.careerId)})).filter((s):s is typeof s&{career:Career}=>!!s.career);
 const persistAssessment=(responses:Responses)=>{if(userId)void onSaveAssessment(responses,state.assessmentSessionId,questionIds,index);};
 const update=(value:number)=>{const assessment={...state.assessment,[q.id]:value};setState({...state,assessment,assessmentComplete:false});void persistAssessment(assessment);};
 const newAttempt=async()=>{setAttemptError('');try{const attemptNumber=state.assessmentHistory.length+1;const nextQuestionIds=selectBalancedQuestionIds(attemptNumber);const id=userId?(await startAssessmentAttempt(userId,attemptNumber)).id:`demo-${crypto.randomUUID()}`;setState({...state,assessment:{},assessmentComplete:false,assessmentSessionId:id,assessmentQuestionIds:nextQuestionIds,assessmentIndex:0,assessmentHistory:[{id,attemptNumber,status:'in_progress',startedAt:new Date().toISOString()},...state.assessmentHistory]});setIndexState(0);try{localStorage.setItem(indexKey,'0')}catch{}}catch(problem){setAttemptError(problem instanceof Error?problem.message:'Could not start a new attempt.');}}
 if(!ready)return <Shell title="RIASEC interest assessment" subtitle="Loading your saved answers before you continue."><div className="panel" role="status">Loading your saved assessment…</div></Shell>;
 return <Shell title="RIASEC interest assessment" subtitle="Explore the kinds of activities you enjoy. Your answers help you decide what to investigate next.">
 <div className="assessment-wrap"><div className="panel assess-card"><div className="assessment-intro"><span className="result-icon"><Target/></span><p className="eyebrow">INTERESTS, NOT A TEST OF ABILITY</p><h2>RIASEC career interests</h2><p>This original activity questionnaire is inspired by Holland’s six interest areas. It is an exploration tool, not a diagnosis, aptitude test, or validated psychometric instrument.</p><p className="scale-hint">For each activity, choose how much you would enjoy trying it. There are no better or worse answers.</p></div>
 {attemptError&&<p className="form-error" role="alert">{attemptError}</p>}{state.assessmentHistory.length>0&&<details className="assessment-history"><summary>Assessment history ({state.assessmentHistory.length} attempts)</summary>{state.assessmentHistory.map(item=><p key={item.id}>Attempt {item.attemptNumber} · {item.status.replace('_',' ')} · {new Date(item.startedAt).toLocaleDateString()}</p>)}</details>}<div className="assessment-tabs"><button className={!state.assessmentComplete?'active':''} onClick={()=>setState({...state,assessmentComplete:false})}>Questions</button><button className={state.assessmentComplete?'active':''} disabled={answered===0} onClick={()=>setState({...state,assessmentComplete:true})}>Results {answered>0&&<span>({answered}/{questionSet.length})</span>}</button></div>{userId&&<p className={saveState==='error'?'form-error':'muted'} role={saveState==='error'?'alert':'status'} aria-live="polite">{saveState==='saving'?'Saving your answers to Supabase…':saveState==='saved'?'Answers saved to your account.':saveState==='error'?<>Could not save your answers: {saveError} <button className="skip-link" onClick={()=>void persistAssessment(state.assessment)}>Retry save</button></>:''}</p>}
 {!state.assessmentComplete?<><div className="wizard-progress-head"><span>ACTIVITY {index+1} OF {questionSet.length} · {dimensions[q.dimension].name.toUpperCase()}</span><span>{answered} answered</span></div><div className="progress-track"><span style={{width:`${(index+1)/questionSet.length*100}%`}}/></div><div className="question-block"><h2>{q.statement}</h2><p>How much would you enjoy trying this activity?</p></div><div className="riasec-scale" role="radiogroup" aria-label="Interest response scale">{riasecScale.map(item=><label className={`answer ${state.assessment[q.id]===item.value?'selected':''}`} key={item.value}><input className="answer-radio" type="radio" name={`riasec-${q.id}`} value={item.value} checked={state.assessment[q.id]===item.value} onChange={()=>update(item.value)}/><span>{item.label}</span></label>)}</div>{state.assessment[q.id]!==undefined&&<button className="skip-link clear-answer" onClick={()=>{const next={...state.assessment};delete next[q.id];setState({...state,assessment:next,assessmentComplete:false});void persistAssessment(next);}}>Clear this answer</button>}<div className="wizard-footer"><button className="button secondary" disabled={index===0} onClick={()=>setIndex(Math.max(index-1,0))}><ChevronLeft size={16}/> Back</button><button className="button primary" onClick={()=>index<questionSet.length-1?setIndex(index+1):setState({...state,assessmentComplete:true})}>{index<questionSet.length-1?'Continue':'See results'} <ChevronRight size={16}/></button></div><button className="skip-link" onClick={()=>index<questionSet.length-1?setIndex(index+1):setState({...state,assessmentComplete:true})}>Skip this activity</button><button className="skip-link" onClick={()=>void newAttempt()}>Start a separate attempt</button></>:<div className="riasec-results"><p className="eyebrow">YOUR INTEREST PROFILE {result.complete?'':'· PROVISIONAL'}</p><h2>{result.complete?'Three areas to explore':'A partial view of your interests'}</h2><p className="results-intro">{result.complete?'These are relative interest patterns from your answers, not a career-fit score. Similar scores can reflect overlapping interests.':'Unanswered activities are excluded, not treated as dislikes. Answer more activities for a fuller view.'} Scores use the mean of answered items in each area, normalized to 0–100 from the 1–5 response range. Each item contributes equally.</p><div className="score-list">{(Object.keys(dimensions) as Dimension[]).map(d=><div className="score-row" key={d}><span className="score-letter">{d}</span><div><b>{dimensions[d].name}</b><div className="score-track"><span style={{width:`${result.scores[d]??0}%`}}/></div></div><span className="score-number">{result.scores[d]===null?'—':result.scores[d]}</span></div>)}</div>
 <div className="top-dimensions"><h3>{result.top.length?'Leading themes':'No answers yet'}</h3>{result.top.length?result.top.map(d=><article className="dimension-card" key={d}><b>{dimensions[d].name}</b><p>{dimensions[d].description}</p><span>Try: {dimensions[d].activity}</span></article>):<p>Answer a few activities to see your interest profile.</p>}</div>
 <div className="top-dimensions all-dimensions"><h3>What each dimension describes</h3>{(Object.keys(dimensions) as Dimension[]).map(d=><article className="dimension-card" key={d}><b>{dimensions[d].name} · {result.scores[d]===null?'Not enough answers':`${result.scores[d]}/100`}</b><p>{dimensions[d].description}</p><span>Try: {dimensions[d].activity}</span></article>)}</div>
 {suggested.length>0&&<div className="assessment-careers"><h3>Career areas to explore</h3><p>These transparent mappings connect your leading themes to catalog career areas. They are prompts for exploration, not predictions of fit or success.</p>{suggested.map(s=>{const c=s.career;const isCompared=compareIds.includes(c.id);return <article className="assessment-career-card" key={c.id}><div className="assessment-suggestion"><Link to={`/careers/${c.id}`}>{c.name}<ArrowUpRight size={14}/></Link><button onClick={()=>setState({...state,career:c.id})}>Set direction</button><button onClick={()=>setState({...state,dismissedSuggestions:[...state.dismissedSuggestions,c.id]})}>Dismiss</button></div><p><b>Why it appears:</b> {explainCareerSuggestion(s.reasons)} Explore whether its focus on {c.interests.slice(0,2).join(' and ')} appeals to you.</p><p><b>Trade-offs to investigate:</b> {c.consider}</p><div className="assessment-career-actions"><button className={`compare-button ${isCompared?'chosen':''}`} onClick={()=>setCompareIds(isCompared?compareIds.filter(id=>id!==c.id):compareIds.length<2?[...compareIds,c.id]:[compareIds[1],c.id])}>{isCompared?'Remove from comparison':'Compare this career'}</button><Link className="compare-button" to="/roadmap-generator" onClick={()=>setState({...state,career:c.id})}>Use for roadmap</Link></div></article>})}{compareIds.length===2&&<div className="assessment-compare"><h4>Compare these possibilities</h4>{compareIds.map(id=>{const c=careers.find(x=>x.id===id);const match=c?matchCareer(c,{riasecScores:result.scores}):null;return c&&match?<article key={id}><b><Link to={`/careers/${id}`}>{c.name}</Link></b><p>{c.desc}</p><p><b>Interest alignment:</b> {match.factors.interest===null?'Unavailable':`${match.factors.interest}% relative alignment`}</p><p><b>Current linked skills:</b> {match.relevantEvidence.map(item=>item.name).join(', ')||'No matching linked evidence'}</p><p><b>Skills not yet evidenced:</b> {match.notYetEvidenced.map(item=>item.name).join(', ')||'Unavailable'}</p><p><b>Interests:</b> {c.interests.join(', ')}</p><p><b>Skills to explore:</b> {c.skills.join(', ')}</p><p><b>Trade-offs:</b> {c.consider}</p></article>:null})}</div>}</div>}
 <div className="wizard-footer"><button className="button secondary" onClick={()=>{setState({...state,assessmentComplete:false});setIndex(0)}}>Review answers</button><button className="button secondary" onClick={()=>void newAttempt()}>Start new attempt</button><Link className="button primary" to="/career-intelligence">Explore recommendations <ArrowRight size={15}/></Link></div></div>}</div><p className="disclaimer">Interest framework basis: Holland’s RIASEC model. Aayam’s question statements are original and unvalidated. Scores describe only answers to these activities and should not be used for high-stakes decisions.</p></div></Shell>
}

function CareerIntelligence({state,setState,userId}:{state:State;setState:(s:State)=>void;userId?:string}){
 const {careers,loading}=useCareerCatalog();const [evidence,setEvidence]=useState<SkillEvidence[]>([]);const [evidenceReady,setEvidenceReady]=useState(!userId);const [evidenceError,setEvidenceError]=useState('');const [retry,setRetry]=useState(0);const [search,setSearch]=useState('');const [group,setGroup]=useState('All');const [sort,setSort]=useState<'match'|'name'>('match');const [theme,setTheme]=useState('All');const [compared,setCompared]=useState<string[]>([]);const [saveError,setSaveError]=useState('');
 useEffect(()=>{if(!userId)return;let active=true;setEvidenceReady(false);setEvidenceError('');loadSkillEvidence(userId).then(rows=>{if(active){setEvidence(rows);setEvidenceReady(true);}}).catch(error=>{if(active){setEvidenceError(error instanceof Error?error.message:'Skill evidence could not be loaded.');setEvidenceReady(true);}});return()=>{active=false;};},[userId,retry]);
 const scores=Object.keys(state.assessment).length?scoreAssessment(state.assessment).scores:undefined;
 const evidenceIds=userId?evidence.filter(item=>item.evidence_type!=='self_reported').map(item=>item.skill_id):state.entries.filter(entry=>!!entry.skillId).map(entry=>entry.skillId as string);
 const ranked=rankCareers(careers,{riasecScores:scores,profileInterests:state.profile?.interests,evidencedSkillIds:evidenceIds,skillEvidenceLoaded:evidenceReady&&!evidenceError});
 let rows=ranked.filter(({career})=>(group==='All'||career.group===group)&&(theme==='All'||career.riasecDimensions.includes(theme))&&`${career.name} ${career.desc} ${career.skills.join(' ')}`.toLocaleLowerCase().includes(search.toLocaleLowerCase()));
 if(sort==='name')rows=[...rows].sort((a,b)=>a.career.name.localeCompare(b.career.name));
 const toggleCompare=(id:string)=>setCompared(compared.includes(id)?compared.filter(item=>item!==id):compared.length<4?[...compared,id]:[...compared.slice(1),id]);
 return <Shell title="Career intelligence" subtitle="A transparent, data-driven starting point for exploring career options. Scores are not predictions of success."><CareerCatalogNotice/>{saveError&&<p className="form-error" role="alert">{saveError}</p>}{!scores&&!state.profile?.interests.length&&<div className="notice recommendation-note"><Lightbulb size={17}/> A completed interest reflection or profile interests can make recommendations more specific. Missing information does not count against a career. <Link to="/assessment">Start the assessment</Link></div>}{evidenceError&&<div className="form-error" role="alert">{evidenceError} <button className="skip-link" onClick={()=>setRetry(value=>value+1)}>Retry skill evidence load</button></div>}<div className="career-tools"><label className="search-box"><Search size={18}/><input aria-label="Search recommendations" placeholder="Search careers or skills" value={search} onChange={event=>setSearch(event.target.value)}/></label><select aria-label="Filter by career category" value={group} onChange={event=>setGroup(event.target.value)}><option>All</option>{[...new Set(careers.map(c=>c.group))].map(value=><option key={value}>{value}</option>)}</select><select aria-label="Filter by interest theme" value={theme} onChange={event=>setTheme(event.target.value)}><option value="All">All interest themes</option>{Object.entries(dimensions).map(([key,value])=><option key={key} value={key}>{value.name}</option>)}</select><select aria-label="Sort recommendations" value={sort} onChange={event=>setSort(event.target.value as 'match'|'name')}><option value="match">Sort by available match data</option><option value="name">Sort by name</option></select></div>{loading||!evidenceReady?<div className="panel" role="status">Loading catalog and your available evidence…</div>:rows.length===0?<div className="panel empty-state"><h2>No matching careers</h2><p>Clear a filter or broaden the search.</p><button className="button secondary" onClick={()=>{setSearch('');setGroup('All');setTheme('All')}}>Clear filters</button></div>:<div className="career-grid">{rows.map(({career,match})=><article className="panel career-card intelligence-card" key={career.id}><div className="career-head"><span className="category-label">{career.group}</span><button className={`icon-button ${state.saved.includes(career.id)?'favorited':''}`} aria-label={state.saved.includes(career.id)?`Remove ${career.name} from saved careers`:`Save ${career.name}`} onClick={()=>toggleSavedCareer(state,setState,userId,career.id,setSaveError)}><Heart size={18} fill={state.saved.includes(career.id)?'currentColor':'none'}/></button></div><h2>{career.name}</h2><p>{career.desc}</p><div className="match-score">{match.score===null?<b>More information needed for a combined score</b>:<><b>{match.score}% available-data match</b><span>{match.dataCoverage}% of matching factors available</span></>}</div><div className="match-factors">{[['Interest',match.factors.interest],['Profile interests',match.factors.statedInterests],['Portfolio / assessed skill evidence',match.factors.evidencedSkills]].map(([label,value])=><span key={String(label)}>{label}: {value===null?'Not available':`${value}%`}</span>)}</div><p className="career-fit"><b>Why it appears</b> {match.reasons.join(' ')||'Explore this option using the career information available.'}</p><p className="small-muted"><b>Skills linked to portfolio or assessed evidence:</b> {match.relevantEvidence.map(skill=>skill.name).join(', ')||'No linked evidence recorded.'}</p><p className="small-muted"><b>Requirements not yet evidenced:</b> {match.notYetEvidenced.map(skill=>skill.name).join(', ')||'No catalog requirements listed.'} This is not proof that you lack these skills.</p><details className="match-details"><summary>Scoring, pathway and limitations</summary><p>Available factors are weighted: interest 65%, profile interests 15%, and linked skill evidence 20%. Unavailable factors are omitted and the remaining weights are renormalized. Skills are described separately from interests.</p><p>{career.path}</p><p>Trade-offs to investigate: {career.consider}</p><p>Only portfolio-linked or independently assessed skill records affect the skills factor; self-reported skills are separate and do not count as demonstrated. Education and qualification compatibility are not scored because reliable structured requirements are not present in the current catalog.</p></details><div className="career-actions"><Link to={`/careers/${career.id}`} className="inline-link">Explore career <ArrowRight size={14}/></Link><button className={`compare-button ${compared.includes(career.id)?'chosen':''}`} onClick={()=>toggleCompare(career.id)}>{compared.includes(career.id)?'Remove compare':'Compare'}</button><Link className="compare-button" to="/roadmap-generator" onClick={()=>setState({...state,career:career.id})}>Generate roadmap</Link></div></article>)}</div>}{compared.length>0&&<div className="panel compare-selection"><b>Selected to compare ({compared.length}/4)</b><span>{compared.map(id=>careers.find(c=>c.id===id)?.name).filter(Boolean).join(' · ')}</span>{compared.length>=2&&<Link className="button secondary" to={`/career-explorer?compare=${compared.join(',')}`}>Open comparison</Link>}</div>}</Shell>;
}

function Careers({state,setState,userId}:{state:State;setState:(s:State)=>void;userId?:string}){const {careers}=useCareerCatalog();const [saveError,setSaveError]=useState('');const [search,setSearch]=useState('');const [group,setGroup]=useState('All');const [theme,setTheme]=useState('All');const [skill,setSkill]=useState('All');const [sort,setSort]=useState('name');const [compare,setCompare]=useState<string[]>([]);const [params]=useSearchParams();useEffect(()=>{const ids=(params.get('compare')||'').split(',').filter(id=>careers.some(c=>c.id===id));if(ids.length)setCompare([...new Set(ids)].slice(0,4));},[]);const groups=[...new Set(careers.map(c=>c.group))];const skills=[...new Set(careers.flatMap(c=>c.skills))].sort();const filtered=careers.filter(c=>(group==='All'||c.group===group)&&(theme==='All'||c.riasecDimensions.includes(theme))&&(skill==='All'||c.skills.includes(skill))&&`${c.name} ${c.desc} ${c.skills.join(' ')}`.toLowerCase().includes(search.toLowerCase()));if(sort==='name')filtered.sort((a,b)=>a.name.localeCompare(b.name));if(sort==='category')filtered.sort((a,b)=>a.group.localeCompare(b.group)||a.name.localeCompare(b.name));const compareCareers=careers.filter(c=>compare.includes(c.id));const comparisonInputs={riasecScores:Object.keys(state.assessment).length?scoreAssessment(state.assessment).scores:undefined,profileInterests:state.profile?.interests,evidencedSkillIds:state.entries.map(entry=>entry.skillId).filter((value):value is string=>!!value),skillEvidenceLoaded:true};const toggleCompare=(id:string)=>setCompare(current=>current.includes(id)?current.filter(item=>item!==id):current.length<4?[...current,id]:[...current.slice(1),id]);return <Shell title="Career explorer" subtitle="Search and compare the published catalog. Missing facts are shown as unavailable, not filled with guesses.">{saveError&&<p className="form-error" role="alert">{saveError}</p>}<div className="career-tools"><label className="search-box"><Search size={18}/><input placeholder="Search careers or skills" value={search} onChange={event=>setSearch(event.target.value)}/></label><select aria-label="Category" value={group} onChange={event=>setGroup(event.target.value)}><option>All</option>{groups.map(value=><option key={value}>{value}</option>)}</select><select aria-label="Interest theme" value={theme} onChange={event=>setTheme(event.target.value)}><option value="All">All interest themes</option>{Object.entries(dimensions).map(([key,value])=><option key={key} value={key}>{value.name}</option>)}</select><select aria-label="Required skill" value={skill} onChange={event=>setSkill(event.target.value)}><option value="All">All skills</option>{skills.map(value=><option key={value}>{value}</option>)}</select><select aria-label="Sort careers" value={sort} onChange={event=>setSort(event.target.value)}><option value="name">Name</option><option value="category">Category</option></select></div>{filtered.length===0?<div className="panel empty-state"><Search/><h2>No careers match those filters</h2><button className="button secondary" onClick={()=>{setSearch('');setGroup('All');setTheme('All');setSkill('All')}}>Clear filters</button></div>:<div className="career-grid">{filtered.map(c=><article className="panel career-card" key={c.id}><div className="career-head"><span className="career-icon"><BriefcaseBusiness size={21}/></span><button className={`icon-button ${state.saved.includes(c.id)?'favorited':''}`} aria-label={state.saved.includes(c.id)?'Remove saved career':'Save career'} onClick={()=>toggleSavedCareer(state,setState,userId,c.id,setSaveError)}><Heart size={18} fill={state.saved.includes(c.id)?'currentColor':'none'}/></button></div><span className="category-label">{c.group}</span><h2>{c.name}</h2><p>{c.desc}</p><div className="skill-chips">{c.skills.map(item=><span key={item}>{item}</span>)}</div><div className="career-actions"><Link to={`/careers/${c.id}`} className="inline-link">Career details <ArrowRight size={14}/></Link><button className={`compare-button ${compare.includes(c.id)?'chosen':''}`} aria-pressed={compare.includes(c.id)} onClick={()=>toggleCompare(c.id)}>{compare.includes(c.id)?'Remove':'Compare'} ({compare.length}/4)</button></div></article>)}</div>}{compareCareers.length>0&&<section className="panel explorer-comparison"><div className="comparison-head"><h2>Career comparison ({compareCareers.length}/4)</h2><button onClick={()=>setCompare([])}>Clear <X size={13}/></button></div>{compareCareers.length===1&&<p>Select at least one more career for a side-by-side view.</p>}<div className="comparison-grid" style={{gridTemplateColumns:`repeat(${compareCareers.length},minmax(0,1fr))`}}>{compareCareers.map(c=>{const match=matchCareer(c,comparisonInputs);return <article key={c.id}><h3><Link to={`/careers/${c.id}`}>{c.name}</Link></h3><p>{c.desc}</p><p><b>Interest alignment:</b> {match.factors.interest===null?'Unavailable':`${match.factors.interest}% relative alignment`}</p><p><b>Current linked skills:</b> {match.relevantEvidence.map(item=>item.name).join(', ')||'No matching linked evidence'}</p><p><b>Skills not yet evidenced:</b> {match.notYetEvidenced.map(item=>item.name).join(', ')||'Unavailable'}</p><p><b>Interests:</b> {c.riasecDimensions.length?c.riasecDimensions.map(d=>dimensions[d as Dimension]?.name||d).join(', '):'Unavailable'}</p><p><b>Skills:</b> {c.skills.join(', ')||'Unavailable'}</p><p><b>Pathway:</b> {c.path||'Unavailable'}</p><p><b>Cost / qualification data:</b> Unavailable in this catalog.</p><Link className="button secondary" to="/roadmap-generator" onClick={()=>setState({...state,career:c.id})}>Create roadmap</Link></article>})}</div></section>}</Shell>}
function CareerDetail({state,setState}:{state:State;setState:(s:State)=>void}){const {careers}=useCareerCatalog();const {id}=useParams();const c=careers.find(x=>x.id===id)||careers[0];const activities=Array.isArray(c.details.activities)?c.details.activities.filter((item):item is string=>typeof item==='string'):[];const qualifications=typeof c.details.qualifications==='string'?c.details.qualifications:'Not available in the current catalog.';const entryPathways=typeof c.details.entry_pathways==='string'?c.details.entry_pathways:'Not available in the current catalog.';return <Shell title={c.name} subtitle={`${c.group} · Illustrative career exploration`}><div className="detail-layout"><div className="detail-main"><article className="panel detail-intro"><span className="career-icon"><BriefcaseBusiness size={22}/></span><h2>Career overview</h2><p>{c.desc}</p><div className="notice"><Lightbulb size={17}/> This is general demo information, not verified market data. Requirements and day-to-day work vary by region and role.</div></article><article className="panel detail-section"><h2>Typical activities</h2>{activities.length?<ul>{activities.map((activity,index)=><li key={`${index}-${activity}`}>{activity}</li>)}</ul>:<p>Typical activities are not documented in the current catalog.</p>}</article><article className="panel detail-section"><h2>Education and entry pathways</h2><p><b>Catalog pathway note (illustrative):</b> {c.path}</p><p><b>Qualifications:</b> {qualifications}</p><p><b>Entry routes:</b> {entryPathways}</p><h3>Questions worth investigating</h3><p>{c.consider}</p><p><b>Costs, salary, and labor-market data:</b> Not available in this catalog.</p></article><article className="panel detail-section"><h2>Skills to explore</h2><div className="skill-chips">{c.skills.map(s=><span key={s}>{s}</span>)}</div><p className="small-muted">These are areas to investigate, not an entry checklist. You can develop them through different routes.</p></article></div><aside className="detail-aside"><article className="panel"><div className="panel-label">EXPLORE THIS PATH</div><h3>Make this your current direction</h3><p>Your selection guides the skill view and learning roadmap.</p><button className="button primary full" onClick={()=>setState({...state,career:c.id})}>Set as career direction <ArrowRight size={15}/></button><Link className="aside-link" to="/skills">Review skill gaps</Link><Link className="aside-link" to="/roadmap-generator">Create a roadmap</Link></article><article className="panel"><div className="panel-label">RELATED CAREERS</div>{careers.filter(x=>x.id!==c.id).slice(0,3).map(x=><Link className="related-link" to={`/careers/${x.id}`} key={x.id}>{x.name}<ArrowUpRight size={14}/></Link>)}</article></aside></div></Shell>}
const roadmap:RoadmapNode[]=[{id:'foundation',title:'Foundations',desc:'Build context in the subjects that underpin your chosen direction.',action:'Choose one topic to learn about and write down three questions.',skills:'Core concepts · Learning habits',effort:'A few short sessions',dependsOn:[]}, {id:'core',title:'Core skills',desc:'Practice one or two relevant skills through guided exercises.',action:'Try a beginner activity in a skill you want to explore.',skills:'Subject knowledge · Practice',effort:'At your own pace',dependsOn:[]}, {id:'practice',title:'Guided practice',desc:'Apply what you are learning to a small, clearly scoped challenge.',action:'Pick a question, gather material, and keep notes on your process.',skills:'Problem solving · Reflection',effort:'A small project',dependsOn:[]}, {id:'project',title:'Real-world project',desc:'Create something useful that demonstrates your thinking.',action:'Make a project for a real audience or question and ask for feedback.',skills:'Applied skills · Communication',effort:'Plan around your schedule',dependsOn:[]}, {id:'portfolio',title:'Portfolio development',desc:'Select evidence and explain what you learned from the process.',action:'Document a project, its decisions, and what you might improve.',skills:'Communication · Reflection',effort:'One focused update',dependsOn:[]}, {id:'next',title:'Career preparation',desc:'Explore next steps and questions to ask someone in the field.',action:'Research a pathway and prepare questions for a trusted mentor.',skills:'Research · Planning',effort:'Ongoing exploration',dependsOn:[]}];
roadmap[1].dependsOn=['foundation']; roadmap[2].dependsOn=['core']; roadmap[3].dependsOn=['practice']; roadmap[4].dependsOn=['project']; roadmap[5].dependsOn=['portfolio'];
function Roadmap({state,setState}:{state:State;setState:(s:State)=>void}){
 const {careers}=useCareerCatalog(); const c=careers.find(x=>x.id===state.career)||careers[0]; const nodes=state.roadmapNodes.length?state.roadmapNodes:roadmap; const [expanded,setExpanded]=useState(nodes[0]?.id||''); const [editing,setEditing]=useState<RoadmapNode|null>(null); const [modalOpen,setModalOpen]=useState(false); const [title,setTitle]=useState(''); const [description,setDescription]=useState(''); const [dependency,setDependency]=useState(''); const [error,setError]=useState(''); const [reorderMessage,setReorderMessage]=useState(''); const completed=nodes.filter(n=>state.done.includes(n.id)).length;
 const startEdit=(node?:RoadmapNode)=>{setModalOpen(true);setEditing(node||null);setTitle(node?.title||'');setDescription(node?.desc||'');setDependency(node?.dependsOn[0]||'');setError('');};
 const hasPath=(from:string,to:string,list:RoadmapNode[],seen=new Set<string>()):boolean=>{if(from===to)return true;if(seen.has(from))return false;seen.add(from);const current=list.find(n=>n.id===from);return !!current?.dependsOn.some(d=>hasPath(d,to,list,seen));};
 const saveNode=(e:FormEvent)=>{e.preventDefault();const id=editing?.id||crypto.randomUUID();const deps=dependency?[dependency]:[];if(deps.includes(id)||deps.some(dep=>hasPath(dep,id,nodes.filter(n=>n.id!==id)))){setError('That prerequisite would create a dependency cycle. Choose a different prerequisite.');return;}
 const next:RoadmapNode={id,title:title.trim(),desc:description.trim(),action:editing?.action||'Choose a small activity and reflect on what you learned.',skills:editing?.skills||'Self-directed learning',effort:editing?.effort||'Illustrative · choose your own pace',dependsOn:deps,custom:true};const updated=editing?nodes.map(n=>n.id===id?next:n):[...nodes,next];setState({...state,roadmapNodes:updated});setExpanded(id);setModalOpen(false);setEditing(null);setTitle('');setDescription('');setDependency('');};
 const remove=(node:RoadmapNode)=>{const children=nodes.filter(n=>n.dependsOn.includes(node.id));if(children.length&&!window.confirm(`“${node.title}” is a prerequisite for ${children.map(n=>n.title).join(', ')}. Remove it and clear those dependencies?`))return;setState({...state,roadmapNodes:nodes.filter(n=>n.id!==node.id).map(n=>({...n,dependsOn:n.dependsOn.filter(d=>d!==node.id)})),done:state.done.filter(id=>id!==node.id)});};
 const reorder=(index:number,delta:number)=>{const target=index+delta;if(target<0||target>=nodes.length)return;const copy=[...nodes];[copy[index],copy[target]]=[copy[target],copy[index]];const positions=new Map(copy.map((node,i)=>[node.id,i]));const invalid=copy.some((node,i)=>node.dependsOn.some(dep=>(positions.get(dep)??-1)>=i));if(invalid){setReorderMessage('That move would place a step before its prerequisite. Update the dependency or choose another order.');return;}setReorderMessage('');setState({...state,roadmapNodes:copy});};
 return <Shell title="Your learning roadmap" subtitle={`A flexible, editable sequence for exploring ${c.name}. Change the order and pace as you learn.`}><div className="roadmap-summary panel"><div><div className="panel-label">CURRENT DIRECTION</div><h2>{c.name}</h2><p>Milestones are suggestions based on your selected direction. Prerequisites are editable.</p></div><div className="roadmap-progress"><span>{completed} / {nodes.length}</span><small>milestones complete</small><div className="mini-progress"><span style={{width:`${nodes.length?completed/nodes.length*100:0}%`}}/></div></div></div>
 <div className="roadmap-toolbar"><div className="view-switch"><button className="active" aria-pressed="true">2D roadmap</button><span>Accessible list view</span></div><button className="button secondary" onClick={()=>startEdit()}><Plus size={15}/> Add milestone</button></div>
 {nodes.length===0&&<div className="panel empty-state"><BookOpen/><h2>Your roadmap is clear</h2><p>Add a milestone when you’re ready to plan a learning step.</p></div>}{reorderMessage&&<div className="form-error" role="status">{reorderMessage}</div>}<div className="timeline">{nodes.map((m,i)=>{const done=state.done.includes(m.id);return <article className={`timeline-item ${done?'completed':''}`} key={m.id}><div className="timeline-marker">{done?<Check size={16}/>:String(i+1).padStart(2,'0')}</div><div className="panel timeline-card"><div className="roadmap-row-tools"><span className="roadmap-node-status">{done?'Completed':i===completed?'In progress':'Upcoming'}</span><button onClick={()=>reorder(i,-1)} disabled={i===0} aria-label={`Move ${m.title} earlier`}>↑</button><button onClick={()=>reorder(i,1)} disabled={i===nodes.length-1} aria-label={`Move ${m.title} later`}>↓</button><button onClick={()=>startEdit(m)} aria-label={`Edit ${m.title}`}>Edit</button>{m.custom&&<button onClick={()=>remove(m)} aria-label={`Remove ${m.title}`}>Remove</button>}</div><button className="timeline-toggle" onClick={()=>setExpanded(expanded===m.id?'':m.id)} aria-expanded={expanded===m.id}><span><small>STAGE {i+1}</small><b>{m.title}</b></span><ChevronDown className={expanded===m.id?'rotated':''}/></button>{expanded===m.id&&<div className="timeline-details"><p>{m.desc}</p><div className="milestone-meta"><span><b>Try:</b> {m.action}</span><span><b>Skills:</b> {m.skills}</span><span><b>Effort:</b> {m.effort}</span>{m.dependsOn.length>0&&<span><b>Prerequisite:</b> {m.dependsOn.map(id=>nodes.find(n=>n.id===id)?.title||'Removed step').join(', ')}</span>}</div><div className="timeline-footer"><span>{state.entries.some(e=>e.type==='Projects')&&i>=2?<Link to="/portfolio">Related portfolio evidence <ArrowRight size={13}/></Link>:'You can add evidence in your portfolio as you go.'}</span><button className={`button ${done?'secondary':'primary'}`} onClick={()=>setState({...state,done:done?state.done.filter(x=>x!==m.id):[...state.done,m.id]})}>{done?'Reopen milestone':'Mark complete'} {!done&&<Check size={15}/>}</button></div></div>}</div></article>})}</div>
 <div className="notice"><Lightbulb size={17}/> Estimated effort is illustrative. Changes are stored locally in demo mode.</div>
 {modalOpen?<div className="modal-backdrop"><div className="modal" role="dialog" aria-modal="true" aria-labelledby="roadmap-edit-title"><div className="modal-head"><div><p className="eyebrow">ROADMAP BUILDER</p><h2 id="roadmap-edit-title">{editing?'Edit milestone':'Add milestone'}</h2></div><button className="icon-button" onClick={()=>startEdit(undefined)} aria-label="Close"><X/></button></div><form onSubmit={saveNode}><label>Title<input required maxLength={120} value={title} onChange={e=>setTitle(e.target.value)}/></label><label>Description<textarea rows={3} value={description} onChange={e=>setDescription(e.target.value)}/></label><label>Prerequisite<select value={dependency} onChange={e=>setDependency(e.target.value)}><option value="">No prerequisite</option>{nodes.filter(n=>n.id!==editing?.id).map(n=><option key={n.id} value={n.id}>{n.title}</option>)}</select></label>{error&&<p className="form-error" role="alert">{error}</p>}<div className="modal-actions"><button type="button" className="button secondary" onClick={()=>setModalOpen(false)}>Cancel</button><button type="submit" className="button primary">Save milestone <Check size={15}/></button></div></form></div></div>:null}</Shell>
}
function RoadmapGenerator({state,userId,mode='generate'}:{state:State;userId?:string;mode?:'generate'|'manage'}){
 const {careers}=useCareerCatalog();const career=careers.find(item=>item.id===state.career);const storageKey=`aayam-roadmaps:${userId||'demo'}`;
 const readLocal=():RoadmapSummary[]=>{try{return JSON.parse(localStorage.getItem(storageKey)||'[]') as RoadmapSummary[]}catch{return[]}};
 const [items,setItems]=useState<RoadmapSummary[]>(readLocal);const [activeId,setActiveId]=useState('');const [loading,setLoading]=useState(!!userId);const [saving,setSaving]=useState(false);const [error,setError]=useState('');const [success,setSuccess]=useState('');const requestKey=useRef('');
 const [form,setForm]=useState({title:career?`Explore ${career.name}`:'',goalDescription:'',startingLevel:'beginner',weeklyTime:state.profile?.time||'',targetDate:'',preferredFormat:''});
 const [selectedStrategy,setSelectedStrategy]=useState<RoadmapStrategy>('balanced');
 const alternatives=roadmapStrategies.map(strategy=>({strategy,tasks:generateCareerRoadmap(career,form,strategy.id)}));
 const [editingGoal,setEditingGoal]=useState(false);const [editForm,setEditForm]=useState(form);const [editingTask,setEditingTask]=useState<RoadmapTask|null>(null);const [taskForm,setTaskForm]=useState({title:'',description:'',effort_note:'',resource_url:'',completion_criteria:'',estimated_time:''});
 const reload=async()=>{if(!userId)return;setLoading(true);try{setItems(await listRoadmaps(userId));setError('');}catch(problem){setError(problem instanceof Error?problem.message:'Roadmaps could not be loaded.');}finally{setLoading(false);}};
 useEffect(()=>{if(userId)void reload();else{setItems(readLocal());setLoading(false);}},[userId,storageKey]);
 useEffect(()=>{if(!userId){try{localStorage.setItem(storageKey,JSON.stringify(items));}catch{setError('Local roadmap storage is full or unavailable.');}}},[items,userId,storageKey]);
 const active=items.find(item=>item.id===activeId)||null;
 const create=(event:FormEvent)=>{event.preventDefault();void(async()=>{setError('');setSuccess('');const normalized=form.title.trim().toLocaleLowerCase();if(items.some(item=>item.status==='active'&&item.title.trim().toLocaleLowerCase()===normalized)){setError('An active roadmap already uses this title. Open it or choose a distinct goal title.');return;}if(form.title.trim().length<2){setError('Enter a goal title with at least two characters.');return;}setSaving(true);const input={...form,title:form.title.trim(),goalDescription:form.goalDescription.trim()};const tasks=generateCareerRoadmap(career,input,selectedStrategy);try{if(userId){if(!requestKey.current)requestKey.current=crypto.randomUUID();await createRoadmap(userId,requestKey.current,career?.id||null,input,tasks);requestKey.current='';const fresh=await listRoadmaps(userId);setItems(fresh);const latest=fresh[0];if(latest)setActiveId(latest.id);}else{const id=crypto.randomUUID();const local:RoadmapSummary={...input,id,careerId:career?.id||null,status:'active',strategy:selectedStrategy,updatedAt:new Date().toISOString(),tasks:tasks.map(task=>({...task,id:crypto.randomUUID(),status:'upcoming'}))};setItems(current=>[local,...current]);setActiveId(id);}setSuccess('Roadmap created and saved.');}catch(problem){setError(problem instanceof Error?problem.message:'Could not create this roadmap.');}finally{setSaving(false);}})();};
 const updateStatus=(item:RoadmapSummary,status:RoadmapSummary['status'])=>{void(async()=>{setError('');try{if(userId)await setRoadmapStatus(userId,item.id,status);setItems(current=>current.map(row=>row.id===item.id?{...row,status,updatedAt:new Date().toISOString()}:row));setSuccess(`Roadmap ${status==='active'?'resumed':status}.`);}catch(problem){setError(problem instanceof Error?problem.message:'Could not update roadmap status.');}})();};
 const deleteItem=(item:RoadmapSummary)=>{if(!window.confirm(`Delete “${item.title}” and its tasks? This cannot be undone.`))return;void(async()=>{try{if(userId)await removeRoadmap(userId,item.id);setItems(current=>current.filter(row=>row.id!==item.id));if(activeId===item.id)setActiveId('');setSuccess('Roadmap deleted.');}catch(problem){setError(problem instanceof Error?problem.message:'Could not delete this roadmap.');}})();};
 const toggleTask=(item:RoadmapSummary,task:RoadmapTask)=>{const status=task.status==='completed'?'upcoming':'completed';void(async()=>{try{if(userId)await updateRoadmapTaskStatus(userId,item.id,task.id,status);setItems(current=>current.map(row=>row.id===item.id?{...row,updatedAt:new Date().toISOString(),tasks:row.tasks.map(t=>t.id===task.id?{...t,status}:t)}:row));setSuccess(status==='completed'?'Task marked complete.':'Task reopened.');}catch(problem){setError(problem instanceof Error?problem.message:'Could not update task progress.');}})();};
 const saveGoal=(event:FormEvent)=>{event.preventDefault();if(!active)return;void(async()=>{try{const input={...editForm,title:editForm.title.trim(),goalDescription:editForm.goalDescription.trim()};if(userId)await updateRoadmapGoal(userId,active.id,input);setItems(current=>current.map(row=>row.id===active.id?{...row,...input,updatedAt:new Date().toISOString()}:row));setEditingGoal(false);setSuccess('Roadmap goal updated. Completed tasks and progress were preserved.');}catch(problem){setError(problem instanceof Error?problem.message:'Could not update roadmap goal.');}})();};
 const saveTask=(event:FormEvent)=>{event.preventDefault();if(!active||!editingTask)return;void(async()=>{try{if(userId)await updateRoadmapTask(userId,editingTask.id,taskForm);setItems(current=>current.map(row=>row.id===active.id?{...row,tasks:row.tasks.map(task=>task.id===editingTask.id?{...task,...taskForm}:task)}:row));setEditingTask(null);setSuccess('Task updated.');}catch(problem){setError(problem instanceof Error?problem.message:'Could not update task.');}})();};
 return <Shell title={mode==='manage'?'My roadmaps':'Roadmap generator'} subtitle={mode==='manage'?'Open and manage your saved goals and progress.':'Create separate, catalog-informed learning plans for different goals. Templates are deterministic suggestions, not AI output or official qualification paths.'}>{error&&<p className="form-error" role="alert">{error}</p>}{success&&<p className="notice" role="status">{success}</p>}
 <div className={`roadmap-generator-layout ${mode==='manage'?'manage-only':''}`}>{mode==='generate'&&<section className="panel"><p className="eyebrow">NEW ROADMAP</p><h2>What would you like to work toward?</h2>{career?.skillRequirements.length?<p>Using catalog requirements for {career.name}.</p>:<p className="notice">No career-specific requirements are available for the selected direction. The generator will use a clearly labeled basic exploration template.</p>}<form onSubmit={create}><label>Goal title<input required minLength={2} maxLength={120} value={form.title} onChange={event=>setForm({...form,title:event.target.value})} placeholder="e.g. Learn Python for data analysis"/></label><label>Goal description<textarea rows={3} value={form.goalDescription} onChange={event=>setForm({...form,goalDescription:event.target.value})} placeholder="What would you like to be able to do?"/></label><div className="form-grid"><label>Starting skill level<select value={form.startingLevel} onChange={event=>setForm({...form,startingLevel:event.target.value})}>{['beginner','some experience','intermediate','advanced'].map(value=><option key={value}>{value}</option>)}</select></label><label>Weekly time<input value={form.weeklyTime} onChange={event=>setForm({...form,weeklyTime:event.target.value})} placeholder="e.g. 3–5 hours"/></label></div><label>Target date (optional)<input type="date" value={form.targetDate} onChange={event=>setForm({...form,targetDate:event.target.value})}/></label><label>Preferred learning format (optional)<input value={form.preferredFormat} onChange={event=>setForm({...form,preferredFormat:event.target.value})} placeholder="e.g. reading, video, hands-on"/></label><fieldset className="roadmap-strategies"><legend>Compare learning approaches</legend><div className="roadmap-strategy-grid">{alternatives.map(({strategy,tasks})=>{const skillCount=new Set(tasks.map(task=>task.skill_id).filter(Boolean)).size;return <button key={strategy.id} type="button" aria-pressed={selectedStrategy===strategy.id} className={`roadmap-strategy-card ${selectedStrategy===strategy.id?'selected':''}`} onClick={()=>setSelectedStrategy(strategy.id)}><span className="strategy-title">{strategy.name}{selectedStrategy===strategy.id&&<Check size={15}/>}</span><span className="strategy-intensity">{strategy.intensity}</span><span className="strategy-stats">{tasks.length} steps · {skillCount?`${skillCount} catalog skills`:'general exploration'}</span><small>{strategy.tradeoff}</small><span className="strategy-sequence">{tasks.slice(0,3).map(task=>task.title).join(' → ')}{tasks.length>3?' → …':''}</span></button>})}</div><p className="small-muted">Task time ranges are estimates; this preview does not promise a completion date. Prerequisites are kept in sequence.</p></fieldset><button className="button primary" disabled={saving}>{saving?'Creating roadmap…':'Create selected roadmap'} <ArrowRight size={15}/></button></form></section>}
 <section className="panel roadmap-list-panel"><div className="section-row"><div><p className="eyebrow">MY ROADMAPS</p><h2>Your goals</h2></div><span>{items.length} total</span></div>{loading?<p role="status">Loading your saved roadmaps…</p>:items.length===0?<div className="empty-state"><BookOpen/><h3>No roadmaps yet</h3><p>Create one for a career, skill, project, or other learning goal.</p><Link className="button secondary" to="/roadmap-generator">Create a roadmap</Link></div>:<div className="roadmap-list">{items.map(item=><article className={`roadmap-list-card ${activeId===item.id?'active':''}`} key={item.id}><button className="roadmap-list-open" onClick={()=>setActiveId(activeId===item.id?'':item.id)}><b>{item.title}</b><span>{roadmapStrategies.find(strategy=>strategy.id===item.strategy)?.name||'Balanced Path'} · {item.status} · {item.tasks.filter(task=>task.status==='completed').length}/{item.tasks.length} tasks complete</span></button><div className="roadmap-list-actions"><button onClick={()=>updateStatus(item,item.status==='active'?'paused':'active')} aria-label={item.status==='paused'?'Resume roadmap':'Pause roadmap'}>{item.status==='active'?'Pause':'Resume'}</button>{item.status!=='archived'&&<button onClick={()=>updateStatus(item,'archived')}>Archive</button>}<button onClick={()=>deleteItem(item)}>Delete</button></div></article>)}</div>}</section></div>
 {active&&<section className="panel roadmap-generator-detail"><div className="section-row"><div><p className="eyebrow">{roadmapStrategies.find(strategy=>strategy.id===active.strategy)?.name||'BALANCED PATH'} · {active.status.toUpperCase()}</p><h2>{active.title}</h2><p>{active.goalDescription||'No additional goal description.'}</p><p className="small-muted">Start: {active.startingLevel} · Time: {active.weeklyTime||'not provided'} · Target: {active.targetDate||'not set'} · Format: {active.preferredFormat||'not provided'}</p></div><button className="button secondary" onClick={()=>{setEditForm({...active,targetDate:active.targetDate||''});setEditingGoal(true)}}>Edit goal</button></div><div className="task-list">{active.tasks.map((task,index)=><article className={`panel task-card ${task.status==='completed'?'completed':''}`} key={task.id}><div><small>STEP {index+1} · {task.task_type.replace('_',' ')}</small><h3>{task.title}</h3><p>{task.description}</p><p><b>Complete when:</b> {task.completion_criteria||'Review the task and record what you learned.'}</p><p className="small-muted">{task.estimated_time||task.effort_note}{task.depends_on.length?` · After ${task.depends_on.map(key=>active.tasks.find(dependency=>dependency.client_key===key)?.title||key).join(', ')}`:''}</p>{task.resource_url&&<a href={task.resource_url} target="_blank" rel="noreferrer">Open learning resource</a>}</div><div className="task-actions"><button className="button secondary" onClick={()=>{setEditingTask(task);setTaskForm({title:task.title,description:task.description,effort_note:task.effort_note,resource_url:task.resource_url,completion_criteria:task.completion_criteria,estimated_time:task.estimated_time})}}>Edit task</button><button className={`button ${task.status==='completed'?'secondary':'primary'}`} onClick={()=>toggleTask(active,task)}>{task.status==='completed'?'Mark incomplete':'Mark complete'}</button></div></article>)}</div></section>}
 {editingGoal&&active&&<div className="modal-backdrop"><div className="modal" role="dialog" aria-modal="true"><h2>Edit roadmap goal</h2><form onSubmit={saveGoal}><label>Title<input required value={editForm.title} onChange={event=>setEditForm({...editForm,title:event.target.value})}/></label><label>Description<textarea value={editForm.goalDescription} onChange={event=>setEditForm({...editForm,goalDescription:event.target.value})}/></label><label>Starting level<input value={editForm.startingLevel} onChange={event=>setEditForm({...editForm,startingLevel:event.target.value})}/></label><label>Weekly time<input value={editForm.weeklyTime} onChange={event=>setEditForm({...editForm,weeklyTime:event.target.value})}/></label><label>Target date<input type="date" value={editForm.targetDate} onChange={event=>setEditForm({...editForm,targetDate:event.target.value})}/></label><label>Preferred format<input value={editForm.preferredFormat} onChange={event=>setEditForm({...editForm,preferredFormat:event.target.value})}/></label><div className="modal-actions"><button type="button" className="button secondary" onClick={()=>setEditingGoal(false)}>Cancel</button><button className="button primary">Save goal</button></div></form></div></div>}
 {editingTask&&<div className="modal-backdrop"><div className="modal" role="dialog" aria-modal="true"><h2>Edit roadmap task</h2><form onSubmit={saveTask}><label>Title<input required value={taskForm.title} onChange={event=>setTaskForm({...taskForm,title:event.target.value})}/></label><label>Description<textarea value={taskForm.description} onChange={event=>setTaskForm({...taskForm,description:event.target.value})}/></label><label>Resource URL<input type="url" value={taskForm.resource_url} onChange={event=>setTaskForm({...taskForm,resource_url:event.target.value})}/></label><label>Completion criteria<input value={taskForm.completion_criteria} onChange={event=>setTaskForm({...taskForm,completion_criteria:event.target.value})}/></label><label>Estimated time<input value={taskForm.estimated_time} onChange={event=>setTaskForm({...taskForm,estimated_time:event.target.value})}/></label><div className="modal-actions"><button type="button" className="button secondary" onClick={()=>setEditingTask(null)}>Cancel</button><button className="button primary">Save task</button></div></form></div></div>}</Shell>;
}

function Skills({state}:{state:State}){
 const {careers,skills}=useCareerCatalog();const [selected,setSelected]=useState('');const [evidence,setEvidence]=useState<SkillEvidence[]>(()=>{try{return JSON.parse(localStorage.getItem('aayam-demo-skill-evidence')||'[]') as SkillEvidence[]}catch{return[]}});const [loading,setLoading]=useState(false);const [error,setError]=useState('');const [userId,setUserId]=useState<string>();const [skillId,setSkillId]=useState('');const [note,setNote]=useState('');const [saving,setSaving]=useState(false);const [search,setSearch]=useState('');const [evidenceFilter,setEvidenceFilter]=useState('all');const [sort,setSort]=useState('priority');const c=careers.find(x=>x.id===state.career)||careers[0];
 useEffect(()=>{let active=true;supabase?.auth.getUser().then(({data})=>{if(active)setUserId(data.user?.id);});return()=>{active=false;};},[]);
 const refresh=async()=>{if(!userId)return;setLoading(true);try{setEvidence(await loadSkillEvidence(userId));setError('');}catch(problem){setError(problem instanceof Error?problem.message:'Could not load skill evidence.');}finally{setLoading(false);}};
 useEffect(()=>{if(userId)void refresh();},[userId]);
 const visibleSkills=c.skillRequirements.length?c.skillRequirements:skills.map(item=>({id:item.id,name:item.name,notes:item.description,relevance:'not specified'}));
 const recordsFor=(id:string)=>evidence.filter(item=>item.skill_id===id);
 const hasPortfolioEvidence=(id:string)=>recordsFor(id).some(item=>item.evidence_type==='portfolio_supported'||item.evidence_type==='independently_assessed');
 const linkedCount=visibleSkills.filter(skill=>hasPortfolioEvidence(skill.id)).length;
 const selfReportedCount=visibleSkills.filter(skill=>recordsFor(skill.id).some(item=>item.evidence_type==='self_reported')&&!hasPortfolioEvidence(skill.id)).length;
 const noRecordCount=visibleSkills.filter(skill=>recordsFor(skill.id).length===0).length;
 const getStatus=(id:string)=>{const rows=recordsFor(id);if(rows.some(item=>item.evidence_type==='independently_assessed'))return'independently_assessed';if(rows.some(item=>item.evidence_type==='portfolio_supported'))return'portfolio_supported';if(rows.some(item=>item.evidence_type==='self_reported'))return'self_reported';return'not_recorded';};
 let displayedSkills=visibleSkills.filter(skill=>`${skill.name} ${skill.notes} ${skill.relevance}`.toLocaleLowerCase().includes(search.toLocaleLowerCase()));
 if(evidenceFilter!=='all')displayedSkills=displayedSkills.filter(skill=>getStatus(skill.id)===evidenceFilter);
 const priority=(value:string)=>/essential|required|critical/i.test(value)?0:/important/i.test(value)?1:/optional/i.test(value)?2:3;
 displayedSkills=[...displayedSkills].sort((a,b)=>sort==='name'?a.name.localeCompare(b.name):priority(a.relevance)-priority(b.relevance)||a.name.localeCompare(b.name));
 const addEvidence=(event:FormEvent)=>{event.preventDefault();if(!skillId)return;setSaving(true);if(!userId){const record:SkillEvidence={id:crypto.randomUUID(),skill_id:skillId,evidence_type:'self_reported',portfolio_entry_id:null,note,created_at:new Date().toISOString()};const next=[record,...evidence];setEvidence(next);try{localStorage.setItem('aayam-demo-skill-evidence',JSON.stringify(next));setError('');setSkillId('');setNote('');}catch{setError('Local evidence could not be saved in this browser.');}finally{setSaving(false);}return;}void recordSkillEvidence({userId,skillId,evidenceType:'self_reported',note}).then(refresh).then(()=>{setSkillId('');setNote('');}).catch(problem=>setError(problem instanceof Error?problem.message:'Could not save evidence.')).finally(()=>setSaving(false));};
 return <Shell title="Skill gaps" subtitle={`Catalog requirements for ${c.name}. Unknown proficiency is not treated as low proficiency.`}>
  <div className="notice"><Lightbulb size={17}/> Evidence describes what you have recorded; no catalog proficiency levels are available, so Aayam does not estimate mastery or employability.</div>
  {error&&<p className="form-error" role="alert">{error} <button className="skip-link" onClick={()=>void refresh()}>Retry</button></p>}
  {loading&&<p role="status">Loading your skill evidence…</p>}
  <div className="skill-evidence-summary"><article className="panel"><b>{linkedCount}</b><span>catalog skills with portfolio or assessment evidence</span></article><article className="panel"><b>{selfReportedCount}</b><span>skills with self-reported notes only</span></article><article className="panel"><b>{noRecordCount}</b><span>skills with no recorded evidence</span></article></div>
  <div className="career-tools skills-tools"><label className="search-box"><Search size={17}/><input aria-label="Search catalog skills" placeholder="Search catalog skills" value={search} onChange={event=>setSearch(event.target.value)}/></label><select aria-label="Filter by evidence" value={evidenceFilter} onChange={event=>setEvidenceFilter(event.target.value)}><option value="all">All evidence states</option><option value="not_recorded">Not yet evidenced</option><option value="self_reported">Self-reported only</option><option value="portfolio_supported">Portfolio supported</option><option value="independently_assessed">Independently assessed</option></select><select aria-label="Sort skills" value={sort} onChange={event=>setSort(event.target.value)}><option value="priority">Catalog priority</option><option value="name">Name</option></select></div>
  {displayedSkills.length===0?<div className="panel empty-state"><Target/><h2>No catalog skills match</h2><p>Change the evidence filter or search term.</p><button className="button secondary" onClick={()=>{setSearch('');setEvidenceFilter('all')}}>Clear filters</button></div>:<div className="skill-list">{displayedSkills.map(skill=>{const records=recordsFor(skill.id);const currentStatus=getStatus(skill.id);const status=currentStatus==='independently_assessed'?'Independently assessed':currentStatus==='portfolio_supported'?'Portfolio supported':currentStatus==='self_reported'?'Self-reported':'Not yet evidenced';const importance=/essential|required|critical/i.test(skill.relevance)?'Essential':/important/i.test(skill.relevance)?'Important':/optional/i.test(skill.relevance)?'Optional':skill.relevance==='not specified'?'Priority not specified':skill.relevance;return <article className="panel skill-row" key={skill.id}><span className={`skill-status ${records.length?'evidence':''}`}>{records.length?<Check size={17}/>:<Target size={17}/>}</span><div className="skill-copy"><h3>{skill.name}</h3><p>{skill.notes||'A career skill requirement from the published catalog.'}</p><span className="skill-priority">Catalog priority: {importance}</span></div><span className="status-label">{status}</span><button className="icon-button" onClick={()=>setSelected(selected===skill.id?'':skill.id)} aria-label={`${selected===skill.id?'Hide':'Show'} next step for ${skill.name}`} aria-expanded={selected===skill.id}><ChevronDown className={selected===skill.id?'rotated':''}/></button>{selected===skill.id&&<div className="skill-expanded"><b>Suggested next step</b><p>Practice {skill.name.toLowerCase()} with a focused activity. Record an artifact in your portfolio if you want to connect practical work to this skill.</p><div className="skill-next-actions"><Link to="/portfolio" className="inline-link">Add portfolio evidence <ArrowRight size={14}/></Link><Link to="/roadmap-generator" className="inline-link">Add to a roadmap <ArrowRight size={14}/></Link></div></div>}</article>})}</div>}
  <form className="panel evidence-form" onSubmit={addEvidence}><h3>Record skill evidence</h3><label>Catalog skill<select required value={skillId} onChange={event=>setSkillId(event.target.value)}><option value="">Choose a skill</option>{skills.length?skills.map(skill=><option key={skill.id} value={skill.id}>{skill.name}</option>):visibleSkills.map(skill=><option key={skill.id} value={skill.id}>{skill.name}</option>)}</select></label><label>Evidence note<textarea required value={note} onChange={event=>setNote(event.target.value)} placeholder="What did you practice or make?"/></label><p className="small-muted">This record is self-reported. It does not independently verify proficiency.</p><button className="button primary" disabled={saving||!skillId}>{saving?'Saving…':'Save skill evidence'}</button></form>
  <div className="skill-legend"><span><i className="legend-dot evidence-dot"/> Portfolio or assessment record</span><span><i className="legend-dot unknown-dot"/> Not yet evidenced</span></div>
 </Shell>;
}
function Portfolio({state,setState,userId}:{state:State;setState:(s:State)=>void;userId?:string}){const {careers,skills}=useCareerCatalog();const [roadmaps,setRoadmaps]=useState<RoadmapSummary[]>([]);useEffect(()=>{let active=true;if(userId){listRoadmaps(userId).then(rows=>{if(active)setRoadmaps(rows)}).catch(()=>{if(active)setRoadmaps([])})}else{try{setRoadmaps(JSON.parse(localStorage.getItem('aayam-roadmaps:demo')||'[]') as RoadmapSummary[])}catch{setRoadmaps([])}}return()=>{active=false}},[userId]);const roadmapTasks=roadmaps.flatMap(roadmap=>roadmap.tasks.map(task=>({id:task.id,label:`${roadmap.title} · ${task.title}`})));const taskLabel=(id?:string)=>roadmapTasks.find(task=>task.id===id)?.label;const portfolioSkills=skills.length?skills:[...new Map(careers.flatMap(career=>career.skillRequirements.map(skill=>[skill.id,{id:skill.id,name:skill.name}]))).values()];const [filter,setFilter]=useState('All');const [modal,setModal]=useState(false);const [editing,setEditing]=useState<Entry|null>(null);const [deleting,setDeleting]=useState<string|null>(null);const [form,setForm]=useState({title:'',type:'Projects',desc:'',skill:'',skillId:'',roadmapNodeId:''});const filters=['All','Projects','Certificates','Assessments','Skills','Competitions','Mentor Feedback'];const items=state.entries.filter(e=>filter==='All'||e.type===filter);const save=(e:FormEvent)=>{e.preventDefault();const selectedSkill=portfolioSkills.find(skill=>skill.id===form.skillId);const entry:Entry={...form,skill:selectedSkill?.name||form.skill,skillId:form.skillId||undefined,roadmapNodeId:form.roadmapNodeId||undefined,id:editing?.id||crypto.randomUUID(),date:editing?.date||new Date().toISOString().slice(0,10)};setState({...state,entries:editing?state.entries.map(x=>x.id===entry.id?entry:x):[entry,...state.entries]});setModal(false);setEditing(null);setForm({title:'',type:'Projects',desc:'',skill:'',skillId:'',roadmapNodeId:''})};const openEdit=(entry:Entry)=>{setEditing(entry);setForm({title:entry.title,type:entry.type,desc:entry.desc,skill:entry.skill,skillId:entry.skillId||'',roadmapNodeId:entry.roadmapNodeId||''});setModal(true)};return <Shell title="My portfolio" subtitle="A personal record of practice, projects, and learning. Evidence is self-declared in this demo."><div className="portfolio-top"><div className="filters portfolio-filters">{filters.map(f=><button onClick={()=>setFilter(f)} className={`filter ${filter===f?'active':''}`} key={f}>{f}</button>)}</div><button className="button primary" onClick={()=>{setEditing(null);setForm({title:'',type:'Projects',desc:'',skill:'',skillId:'',roadmapNodeId:''});setModal(true)}}><Plus size={16}/> Add evidence</button></div>{items.length===0?<div className="panel empty-state"><FolderOpen/><h2>No {filter==='All'?'evidence':filter.toLowerCase()} yet</h2><p>Add a project or learning experience to start building your record.</p><button className="button secondary" onClick={()=>{setEditing(null);setModal(true)}}><Plus size={16}/> Add your first entry</button></div>:<div className="portfolio-grid">{items.map(entry=><article className="panel portfolio-card" key={entry.id}><div className="portfolio-card-head"><span className="entry-icon"><FileText size={19}/></span><div className="entry-actions"><button className="icon-button" aria-label={`Edit ${entry.title}`} onClick={()=>openEdit(entry)}><FileText size={16}/></button><button className="icon-button delete-action" aria-label={`Delete ${entry.title}`} onClick={()=>setDeleting(entry.id)}><Trash2 size={16}/></button></div></div><span className="category-label">{entry.type} · Self-declared</span><h3>{entry.title}</h3><p>{entry.desc}</p><div className="entry-footer"><span>{entry.skill||'Learning evidence'}{taskLabel(entry.roadmapNodeId)&&<small> · {taskLabel(entry.roadmapNodeId)}</small>}</span><time>{entry.date}</time></div></article>)}</div>}{modal&&<div className="modal-backdrop" role="presentation" onMouseDown={e=>{if(e.target===e.currentTarget)setModal(false)}}><div className="modal" role="dialog" aria-modal="true" aria-labelledby="entry-title"><div className="modal-head"><div><p className="eyebrow">PORTFOLIO EVIDENCE</p><h2 id="entry-title">{editing?'Edit entry':'Add an entry'}</h2></div><button className="icon-button" aria-label="Close" onClick={()=>setModal(false)}><X/></button></div><form onSubmit={save}><label>Title<input required value={form.title} onChange={e=>setForm({...form,title:e.target.value})} placeholder="e.g. My first web project"/></label><label>Type<select value={form.type} onChange={e=>setForm({...form,type:e.target.value})}>{filters.slice(1).map(f=><option key={f}>{f}</option>)}</select></label><label>What did you do or learn?<textarea required rows={3} value={form.desc} onChange={e=>setForm({...form,desc:e.target.value})} placeholder="Describe the experience and what you learned"/></label><label>Related catalog skill<select value={form.skillId} onChange={e=>{const selected=skills.find(skill=>skill.id===e.target.value);setForm({...form,skillId:e.target.value,skill:selected?.name||form.skill})}}><option value="">No catalog skill linked</option>{portfolioSkills.map(skill=><option key={skill.id} value={skill.id}>{skill.name}</option>)}</select></label><label>Related roadmap task<select value={form.roadmapNodeId} onChange={e=>setForm({...form,roadmapNodeId:e.target.value})}><option value="">No roadmap task linked</option>{roadmapTasks.map(task=><option key={task.id} value={task.id}>{task.label}</option>)}</select></label><div className="notice"><Lightbulb size={16}/> Portfolio entries remain private to your account or this browser’s local demo. Skill links use the catalog; evidence is self-reported unless independently assessed.</div><div className="modal-actions"><button type="button" className="button secondary" onClick={()=>setModal(false)}>Cancel</button><button className="button primary" type="submit">{editing?'Save changes':'Add entry'} <Check size={15}/></button></div></form></div></div>}{deleting&&<div className="modal-backdrop"><div className="modal confirm-modal" role="alertdialog" aria-modal="true"><span className="delete-icon"><Trash2/></span><h2>Delete this entry?</h2><p>This removes the entry from your local demo portfolio.</p><div className="modal-actions"><button className="button secondary" onClick={()=>setDeleting(null)}>Keep entry</button><button className="button danger" onClick={()=>{setState({...state,entries:state.entries.filter(e=>e.id!==deleting)});setDeleting(null)}}>Delete entry</button></div></div></div>}</Shell>}
function SignIn(){
 const [email,setEmail]=useState('');const [password,setPassword]=useState('');const [creating,setCreating]=useState(false);const [showPassword,setShowPassword]=useState(false);const [message,setMessage]=useState('');const [error,setError]=useState('');const [busy,setBusy]=useState(false);const navigate=useNavigate();const authFeedback=useContext(AuthFeedbackContext);
 const submit=async(e:FormEvent)=>{e.preventDefault();if(!supabase)return;setBusy(true);setMessage('');setError('');authFeedback.setNotice('');try{if(creating){const {data,error:authError}=await supabase.auth.signUp({email,password,options:{emailRedirectTo:`${window.location.origin}/signin`}});if(authError)throw authError;if(data.session){navigate('/onboarding',{replace:true});return;}setMessage('Account created. Check your email to confirm the address, then sign in.');}else{const {error:authError}=await supabase.auth.signInWithPassword({email,password});if(authError)throw authError;navigate('/app',{replace:true});}}catch(e){setError(e instanceof Error?e.message:'Authentication failed. Please try again.');}finally{setBusy(false);}};
 return <main className="auth-page"><header className="auth-header wrap"><Logo/><Link to="/" className="text-link">Back to home</Link></header><div className="auth-layout"><section className="auth-card panel"><span className="auth-symbol"><Sparkles/></span><p className="eyebrow">WELCOME TO AAYAM</p><h1>{supabase?(creating?'Create your Aayam account':'Sign in to your workspace'):'Explore your next step.'}</h1><p className="auth-intro">A thoughtful place to explore careers, build skills, and plan what comes next.</p>{supabase?<form className="auth-form" onSubmit={submit}><div className="auth-field"><label htmlFor="auth-email">Email address</label><input id="auth-email" required type="email" autoComplete="email" value={email} onChange={e=>setEmail(e.target.value)}/></div><div className="auth-field"><label htmlFor="auth-password">Password</label><span className="password-control"><input id="auth-password" required type={showPassword?'text':'password'} minLength={8} autoComplete={creating?'new-password':'current-password'} value={password} onChange={e=>setPassword(e.target.value)}/><button type="button" className="password-toggle" aria-label={showPassword?'Hide password':'Show password'} aria-pressed={showPassword} onClick={()=>setShowPassword(value=>!value)}>{showPassword?<EyeOff size={17}/>:<Eye size={17}/>}</button></span></div>{authFeedback.notice&&<p role="status" className="auth-message">{authFeedback.notice}</p>}{message&&<p role="status" className="auth-message">{message}</p>}{error&&<p role="alert" className="form-error">{error}</p>}<button className="button primary full" type="submit" disabled={busy}>{busy?(creating?'Creating account…':'Signing in…'):creating?'Create account':'Sign in'} <ArrowRight size={16}/></button><button type="button" className="auth-switch" onClick={()=>{setCreating(!creating);setMessage('');setError('');}}>{creating?'Already have an account? Sign in':'New to Aayam? Create an account'}</button><small>Email confirmation is required before first sign-in. Use the same email and password for future visits.</small></form>:<><p>This is a frontend demo. No account or password is needed to explore.</p><Button to="/onboarding">Continue with demo <ArrowRight size={16}/></Button><small>Demo data is stored locally in this browser.</small></>}</section><aside className="auth-aside"><p className="eyebrow">EXPLORE · LEARN · BUILD</p><h2>Your next step can start with a question.</h2><p>Discover careers that fit your interests, understand the skills they ask for, and create a practical plan at your own pace.</p><div className="auth-aside-art" aria-hidden="true"><span/><span/><span/><i/><i/><i/></div><ul><li>Explore career possibilities</li><li>Identify skills to practice</li><li>Build a roadmap that can change with you</li></ul></aside></div></main>}
function NotFound(){return <main className="not-found"><Logo/><h1>That page isn’t here.</h1><p>Find your way back to Aayam and continue exploring.</p><Button to="/">Back to home <ArrowRight size={16}/></Button></main>}
function WorkspaceRoutes({state,setState,userId,workspaceLoaded,saveState,saveError,onSaveAssessment}:{state:State;setState:(s:State)=>void;userId?:string;workspaceLoaded:boolean;saveState:'idle'|'saving'|'saved'|'error';saveError:string;onSaveAssessment:(responses:Responses,sessionId:string|null,questionIds:string[],index:number)=>Promise<string>}){const {careers,skills}=useCareerCatalog();const riasecScores=Object.keys(state.assessment).length?scoreAssessment(state.assessment,state.assessmentQuestionIds).scores:undefined;return <Routes><Route path="/" element={<Landing/>}/><Route path="/signin" element={<SignIn/>}/><Route path="/onboarding" element={<Onboarding state={state} setState={setState}/>}/><Route path="/assessment" element={<Assessment key={`${userId||'demo'}-${workspaceLoaded?'ready':'loading'}`} state={state} setState={setState} userId={userId} ready={workspaceLoaded} saveState={saveState} saveError={saveError} onSaveAssessment={onSaveAssessment}/>}/><Route path="/app" element={<Dashboard state={state} userId={userId}/>}/><Route path="/profile" element={<Onboarding state={state} setState={setState}/>}/><Route path="/career-intelligence" element={<CareerIntelligence state={state} setState={setState} userId={userId}/>}/><Route path="/career-explorer" element={<Careers state={state} setState={setState} userId={userId}/>}/><Route path="/career-universe" element={<Shell title="3D Career Path Explorer" subtitle="Explore real catalog relationships and connect career goals to required skills and saved learning tasks."><CareerPathExplorer careers={careers} skills={skills} userId={userId} riasecScores={riasecScores} profileInterests={state.profile?.interests} onChooseCareer={careerId=>setState({...state,career:careerId})}/></Shell>}/><Route path="/careers" element={<Careers state={state} setState={setState} userId={userId}/>}/><Route path="/careers/:id" element={<CareerDetail state={state} setState={setState}/>}/><Route path="/skills" element={<Skills state={state}/>}/><Route path="/roadmap-generator" element={<RoadmapGenerator state={state} userId={userId}/>}/><Route path="/my-roadmaps" element={<RoadmapGenerator state={state} userId={userId} mode="manage"/>}/><Route path="/roadmap" element={<Roadmap state={state} setState={setState}/>}/><Route path="/portfolio" element={<Portfolio state={state} setState={setState} userId={userId}/>}/><Route path="*" element={<NotFound/>}/></Routes>}
export default function App(){
 const location=useLocation();
 const [state,setState]=useStore();
 const [user,setUser]=useState<{id:string}|null>(null);
 const currentUserId=useRef<string|null>(null);
 const [authReady,setAuthReady]=useState(!supabase);
 const [authError,setAuthError]=useState('');
 const [authRetry,setAuthRetry]=useState(0);
 const [cloudReady,setCloudReady]=useState(!supabase);
 const [workspaceLoaded,setWorkspaceLoaded]=useState(!supabase);
 const [syncStatus,setSyncStatus]=useState<SyncStatus>(supabase?'loading':'local');
 const [syncError,setSyncError]=useState('');
 const [workspaceRetry,setWorkspaceRetry]=useState(0);
 const [assessmentSaveState,setAssessmentSaveState]=useState<'idle'|'saving'|'saved'|'error'>('idle');
 const [assessmentSaveError,setAssessmentSaveError]=useState('');
 const assessmentSaveRun=useRef(0);
 const [authNotice,setAuthNotice]=useState('');
 useEffect(()=>{
  if(!supabase)return;
  let active=true;
  let authEventVersion=0;
  setAuthReady(false);setAuthError('');
  const {data:{subscription}}=supabase.auth.onAuthStateChange((event,session)=>{
   authEventVersion+=1;
   const nextUser=session?.user?{id:session.user.id}:null;
   const identityChanged=currentUserId.current!== (nextUser?.id??null);
   currentUserId.current=nextUser?.id??null;
   if(identityChanged){setState(initial);assessmentSaveRun.current+=1;setAssessmentSaveState('idle');setAssessmentSaveError('');}
   setUser(current=>current?.id===nextUser?.id?current:nextUser);
   setAuthReady(true);setAuthError('');
   if(identityChanged||event==='SIGNED_IN'||event==='SIGNED_OUT'){
    setCloudReady(!nextUser);setWorkspaceLoaded(!nextUser);
   }
   if(event==='SIGNED_OUT')setAuthNotice('You have signed out.');
   if(event==='SIGNED_IN')setAuthNotice('');
  });
  const timeout=window.setTimeout(()=>{
   if(active&&authEventVersion===0){setAuthError('Supabase did not respond while checking your session. Check your connection and retry.');setAuthReady(true);}
  },10000);
  supabase.auth.getSession().then(({data,error})=>{
   if(!active||authEventVersion>0)return;
   window.clearTimeout(timeout);
   if(error){setAuthError(`Could not check your session: ${error.message}`);setAuthReady(true);return;}
   const sessionUser=data.session?.user?{id:data.session.user.id}:null;
   currentUserId.current=sessionUser?.id??null;
   setUser(sessionUser);setAuthError('');setAuthReady(true);
  }).catch(e=>{
   if(!active||authEventVersion>0)return;
   window.clearTimeout(timeout);setAuthError(`Could not check your session: ${e instanceof Error?e.message:'Unexpected error'}`);setAuthReady(true);
  });
  return()=>{active=false;window.clearTimeout(timeout);subscription.unsubscribe();};
 },[authRetry]);
 useEffect(()=>{
  if(!supabase){setCloudReady(true);setWorkspaceLoaded(true);setSyncStatus('local');return;}
  if(!user){setCloudReady(true);setWorkspaceLoaded(false);setSyncStatus('ready');return;}
  let active=true;setSyncStatus('loading');setSyncError('');
  let timeoutId=window.setTimeout(()=>{
   if(active){setCloudReady(true);setWorkspaceLoaded(false);setSyncStatus('error');setSyncError('Workspace loading timed out. Check your connection and retry.');}
  },15000);
  loadWorkspace(user.id,initial).then(remote=>{
   window.clearTimeout(timeoutId);
   if(active){setState({...remote,dismissedSuggestions:state.dismissedSuggestions,roadmapNodes:remote.roadmapNodes});setCloudReady(true);setWorkspaceLoaded(true);setSyncStatus('ready');}
  }).catch(e=>{
   window.clearTimeout(timeoutId);
   if(active){setCloudReady(true);setWorkspaceLoaded(false);setSyncStatus('error');setSyncError(e instanceof Error?e.message:'Could not load your cloud workspace.');}
  });
  return()=>{active=false;window.clearTimeout(timeoutId);};
 },[user?.id,workspaceRetry]);
 useEffect(()=>{
  if(!supabase||!user||!cloudReady||!workspaceLoaded)return;
  const timer=window.setTimeout(()=>{
   setSyncStatus('saving');
   saveWorkspace(user.id,state).then(()=>{setSyncError('');setSyncStatus('saved');}).catch(e=>{setSyncStatus('error');setSyncError(e instanceof Error?e.message:'Could not save your workspace.');});
  },700);
  return()=>window.clearTimeout(timer);
 },[state.profile,state.career,state.done,state.entries,state.saved,state.roadmapNodes,user?.id,cloudReady,workspaceLoaded]);
 const persistAssessmentForUser=async(responses:Responses,sessionId:string|null,questionIds:string[],activeIndex:number):Promise<string>=>{
  if(!supabase||!user)return '';
  const run=++assessmentSaveRun.current;setAssessmentSaveState('saving');setAssessmentSaveError('');
  try{const savedSessionId=await saveAssessment(user.id,responses,sessionId,questionIds,activeIndex);if(run===assessmentSaveRun.current){setAssessmentSaveState('saved');setState(current=>{const status=scoreAssessment(responses,questionIds).complete?'completed':'in_progress';const found=current.assessmentHistory.some(item=>item.id===savedSessionId);const history=found?current.assessmentHistory.map(item=>item.id===savedSessionId?{...item,status}:item):[{id:savedSessionId,attemptNumber:current.assessmentHistory.length+1,status,startedAt:new Date().toISOString()},...current.assessmentHistory];return {...current,assessmentSessionId:savedSessionId,assessmentQuestionIds:questionIds,assessmentIndex:activeIndex,assessmentHistory:history};});}return savedSessionId;}
  catch(e){if(run===assessmentSaveRun.current){setAssessmentSaveState('error');setAssessmentSaveError(e instanceof Error?e.message:'Assessment answers could not be saved.');}return '';}
 };
 if(!authReady)return <div className="auth-page"><p className="panel" role="status">Checking your session…</p></div>;
 if(authError&&location.pathname==='/signin')return <AuthFeedbackContext.Provider value={{notice:authNotice,setNotice:setAuthNotice}}><div className="auth-page"><p className="form-error" role="alert">{authError} <button className="skip-link" onClick={()=>{setAuthReady(false);setAuthRetry(v=>v+1);}}>Retry session check</button></p><Routes><Route path="/signin" element={<SignIn/>}/></Routes></div></AuthFeedbackContext.Provider>;
 if(authError)return <div className="auth-page"><div className="auth-card panel"><p className="form-error" role="alert">{authError}</p><button className="button primary" onClick={()=>{setAuthReady(false);setAuthRetry(v=>v+1);}}>Retry connection</button><p><Link to="/signin">Open sign in</Link></p></div></div>;
 if(supabase&&!user)return <AuthFeedbackContext.Provider value={{notice:authNotice,setNotice:setAuthNotice}}><Routes><Route path="/" element={<Landing/>}/><Route path="/signin" element={<SignIn/>}/><Route path="*" element={<Navigate to="/signin" replace/>}/></Routes></AuthFeedbackContext.Provider>;
 if(user&&!workspaceLoaded&&syncError)return <div className="auth-page"><div className="auth-card panel"><p className="form-error" role="alert">Your workspace could not be loaded: {syncError}</p><button className="button primary" onClick={()=>{setCloudReady(false);setSyncError('');setWorkspaceRetry(v=>v+1);}}>Retry loading workspace</button><button className="skip-link" onClick={async()=>{await supabase?.auth.signOut();}}>Sign out</button></div></div>;
 return <AuthFeedbackContext.Provider value={{notice:authNotice,setNotice:setAuthNotice}}><SyncStatusContext.Provider value={syncStatus}><CareerCatalogProvider><WorkspaceRoutes state={state} setState={setState} userId={user?.id} workspaceLoaded={workspaceLoaded} saveState={assessmentSaveState} saveError={assessmentSaveError} onSaveAssessment={persistAssessmentForUser}/>{syncError&&<div className="form-error" role="alert">Cloud sync issue: {syncError}</div>}{assessmentSaveState==='error'&&<div className="form-error" role="alert">Assessment save failed: {assessmentSaveError} <Link className="inline-link" to="/assessment">Open assessment to retry.</Link></div>}</CareerCatalogProvider></SyncStatusContext.Provider></AuthFeedbackContext.Provider>;
}
